insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('digital-overwhelm-reset', 'Digital Overwhelm Reset', 'worksheet'::resource_kind, 'A short audit of notifications, screens and open tabs that are crowding out a client''s attention.', 'Help a client notice what digital habits are draining their focus and choose one change.', array['Adults', 'Teens']::text[], '15 minutes', 'Most clients underestimate how much of their day is spent reacting to notifications rather than choosing where their attention goes. Walk through a typical day and mark where a screen interrupted something else, then pick one boundary to trial for a week: a phone charging outside the bedroom, one email check block, one app removed from the home screen. Revisit at the next session rather than expecting the change to stick on the first try.', '[{"id": "f0", "type": "textarea", "label": "A typical day, hour by hour, with the moments a screen pulled my attention"}, {"id": "f1", "type": "textarea", "label": "What I was doing right before I picked up my phone"}, {"id": "f2", "type": "textarea", "label": "How I felt in my body in that moment"}, {"id": "f3", "type": "textarea", "label": "One digital boundary I want to try this week"}, {"id": "f4", "type": "textarea", "label": "What might make that boundary hard to keep"}]'::jsonb, array['technology', 'self-monitoring', 'habits']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('life-role-transition-map', 'Life Role Transition Map', 'worksheet'::resource_kind, 'Maps the roles a client is leaving, keeping and taking on during a major life change.', 'Help a client name what a transition is asking them to give up and gain.', array['Adults']::text[], '25 minutes', 'A transition like a new job, retirement, or children leaving home changes a client''s day-to-day identity even when the change itself is wanted. Naming the roles that are ending, continuing and starting gives shape to an otherwise vague sense of unease and opens a conversation about which losses need acknowledging before the client can settle into what comes next.', '[{"id": "f0", "type": "textarea", "label": "The role or routine I''m leaving behind"}, {"id": "f1", "type": "textarea", "label": "What I''ll miss about it"}, {"id": "f2", "type": "textarea", "label": "A role that stays the same through this change"}, {"id": "f3", "type": "textarea", "label": "The new role I''m stepping into"}, {"id": "f4", "type": "textarea", "label": "One thing I''m curious or hopeful about in this next chapter"}]'::jsonb, array['transitions', 'identity', 'life review']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('difficult-conversation-prep-sheet', 'Difficult Conversation Prep Sheet', 'worksheet'::resource_kind, 'Helps a client plan what to say and how to stay grounded before a hard conversation.', 'Give a client a structure for approaching a conversation they''ve been avoiding.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients often rehearse a hard conversation only as a worst-case argument in their head, which makes avoidance more likely. Separating what they want the other person to understand from how they want to say it, plus a plan for staying steady if things get tense, turns a vague dread into something workable. Practicing the opening line out loud in session often does more than the writing.', '[{"id": "f0", "type": "textarea", "label": "The conversation I''ve been avoiding"}, {"id": "f1", "type": "textarea", "label": "What I most want the other person to understand"}, {"id": "f2", "type": "textarea", "label": "How I want to open the conversation"}, {"id": "f3", "type": "textarea", "label": "A sign I''m getting overwhelmed and need to pause"}, {"id": "f4", "type": "textarea", "label": "What I''ll do if I need to pause"}, {"id": "f5", "type": "textarea", "label": "How I''ll know the conversation went well enough"}]'::jsonb, array['communication', 'assertiveness', 'planning']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('weekly-reset-ritual-planner', 'Weekly Reset Ritual Planner', 'worksheet'::resource_kind, 'Builds a short end-of-week routine for closing out unfinished business before rest.', 'Give a client a repeatable way to transition out of a demanding week.', array['Adults']::text[], '15 minutes weekly', 'Some clients carry the week''s unfinished tasks into the weekend because nothing marks the switch from doing to resting. A short, repeatable ritual, closing open tabs, writing tomorrow''s first task, a specific place and activity, gives the mind a cue that it is safe to stop. The content matters less than the repetition; encourage the client to keep it short enough that they will actually do it.', '[{"id": "f0", "type": "textarea", "label": "What usually keeps running in my head after the work week ends"}, {"id": "f1", "type": "textarea", "label": "Three steps I''ll take every Friday to mark the switch"}, {"id": "f2", "type": "textarea", "label": "Where and when I''ll do this ritual"}, {"id": "f3", "type": "textarea", "label": "What rest looks like once the ritual is done"}]'::jsonb, array['routines', 'self-monitoring', 'burnout']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('saying-no-practice-sheet', 'Saying No Practice Sheet', 'worksheet'::resource_kind, 'Gives a client scripted language for declining requests without over-explaining.', 'Build a client''s confidence in setting a limit without a guilt spiral afterward.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients who over-commit often believe a no needs an airtight justification, which turns every request into a negotiation. Practicing a short, warm decline, with no elaborate excuse attached, out loud in session before trying it in real life builds the muscle. Track what actually happens afterward; most clients find the fallout is smaller than the guilt predicted.', '[{"id": "f0", "type": "textarea", "label": "A recent request I said yes to but wish I hadn''t"}, {"id": "f1", "type": "textarea", "label": "A short way I could have declined it"}, {"id": "f2", "type": "textarea", "label": "What I''m afraid will happen if I say no"}, {"id": "f3", "type": "textarea", "label": "One request coming up this week I could practice on"}, {"id": "f4", "type": "textarea", "label": "How I felt afterward, the last time I did say no"}]'::jsonb, array['boundaries', 'assertiveness', 'self-monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('mental-filter-correction-sheet', 'Mental Filter Correction Sheet', 'cbt'::resource_kind, 'Catches the habit of dwelling on one negative detail while filtering out the rest.', 'Help a client notice when one bad moment is coloring their whole read of a day.', array['Adults', 'Teens']::text[], '15 minutes', 'A client replaying one critical comment from a mostly good meeting is filtering out everything that went well. Logging the whole picture next to the detail that has stuck makes the imbalance visible without arguing the client out of the feeling. Over a few entries, a pattern usually appears: a specific type of moment the filter locks onto.', '[{"id": "f0", "type": "textarea", "label": "The one detail that''s stuck with me"}, {"id": "f1", "type": "textarea", "label": "What else actually happened, including what went fine or well"}, {"id": "f2", "type": "textarea", "label": "How much weight I''ve been giving the one detail, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "A more complete way to describe the whole event"}]'::jsonb, array['thinking traps', 'core CBT', 'monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('black-and-white-thinking-scale', 'Black-and-White Thinking Scale', 'cbt'::resource_kind, 'Uses a 0-to-10 line to loosen an all-or-nothing read of a situation.', 'Help a client find the middle ground their thinking has skipped over.', array['Adults', 'Teens']::text[], '15 minutes', 'A client stuck in all-or-nothing language, a total failure, a complete disaster, rarely has room to notice partial outcomes. Drawing a 0-to-10 line and marking where the situation actually falls, then naming what sits at the far ends for comparison, gives the client''s own words something to measure against. This works best with a concrete recent example rather than a hypothetical one.', '[{"id": "f0", "type": "textarea", "label": "The all-or-nothing statement I caught myself thinking"}, {"id": "f1", "type": "textarea", "label": "What a true 0, the worst version, would look like"}, {"id": "f2", "type": "textarea", "label": "What a true 10, the best version, would look like"}, {"id": "f3", "type": "textarea", "label": "Where the actual situation falls on that line"}, {"id": "f4", "type": "textarea", "label": "What that number tells me that the original statement missed"}]'::jsonb, array['thinking traps', 'core CBT', 'perspective']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('readiness-to-change-ruler', 'Readiness to Change Ruler', 'cbt'::resource_kind, 'Scores how important, confident and ready a client feels toward a specific change.', 'Locate where a client''s ambivalence actually sits before setting a goal.', array['Adults', 'Teens']::text[], '15 minutes', 'Pushing a client toward action before they are ready usually backfires into resistance. Scoring importance, confidence and readiness separately on a 0-to-10 scale, then asking why the number is not lower, often surfaces the client''s own reasons for change rather than the clinician''s. Low confidence with high importance points toward a skills gap rather than a motivation problem.', '[{"id": "f0", "type": "textarea", "label": "The change I''m considering"}, {"id": "f1", "type": "textarea", "label": "How important this feels right now, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "How confident I am I could do it, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Why that number and not one lower"}, {"id": "f4", "type": "textarea", "label": "What would need to be true for the number to go up"}]'::jsonb, array['motivation', 'core CBT', 'ambivalence']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('should-statements-rewrite-sheet', 'Should Statements Rewrite Sheet', 'cbt'::resource_kind, 'Trades a rigid should statement for a more flexible, self-chosen version.', 'Loosen the guilt and pressure that rigid rules create.', array['Adults', 'Teens']::text[], '15 minutes', 'Should statements, about the self or other people, carry a hidden rule that rarely survives being said out loud. Writing the rule down, asking where it came from, and rewriting it as a preference rather than a demand takes some of the moral weight out of falling short. Watch for the client applying the same rigid rule to someone else in the room without noticing.', '[{"id": "f0", "type": "textarea", "label": "A should statement I catch myself using often"}, {"id": "f1", "type": "textarea", "label": "Where I think this rule came from"}, {"id": "f2", "type": "textarea", "label": "What happens, in my body or mood, when I break it"}, {"id": "f3", "type": "textarea", "label": "A more flexible version of the same idea"}, {"id": "f4", "type": "textarea", "label": "How that flexible version feels to say out loud"}]'::jsonb, array['thinking traps', 'core CBT', 'self-criticism']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('mind-reading-check-sheet', 'Mind Reading Check Sheet', 'cbt'::resource_kind, 'Separates what a client assumed someone else was thinking from what was actually said.', 'Show a client how often they are reacting to a guess rather than a fact.', array['Adults', 'Teens']::text[], '15 minutes', 'A client who is sure they know what someone else is thinking is usually reacting to their own guess rather than any evidence. Logging the assumed thought next to what the other person actually said or did creates a small, repeatable check. Over several entries the client can start running this check in real time instead of after the fact.', '[{"id": "f0", "type": "textarea", "label": "What I assumed the other person was thinking"}, {"id": "f1", "type": "textarea", "label": "What they actually said or did"}, {"id": "f2", "type": "textarea", "label": "How I reacted based on my assumption"}, {"id": "f3", "type": "textarea", "label": "What I might ask instead of assuming next time"}]'::jsonb, array['thinking traps', 'core CBT', 'evidence']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('values-vs-rules-sort', 'Values vs Rules Sort', 'act'::resource_kind, 'Sorts a client''s stated goals into ones chosen from values and ones inherited as rules.', 'Help a client tell the difference between what they want and what they think they should want.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients often carry a long list of goals without noticing that some come from a felt sense of what matters and others come from an old rule about what a good person does. Sorting a list of goals into these two piles, and sitting with the discomfort of a goal that turns out to be someone else''s rule, opens room for the client to choose deliberately rather than by default.', '[{"id": "f0", "type": "textarea", "label": "A goal or standard I hold myself to"}, {"id": "f1", "type": "textarea", "label": "Where this came from, if I trace it back"}, {"id": "f2", "type": "textarea", "label": "Does this feel chosen or inherited"}, {"id": "f3", "type": "textarea", "label": "If chosen, what value is underneath it"}, {"id": "f4", "type": "textarea", "label": "If inherited, do I want to keep it"}]'::jsonb, array['values', 'core ACT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('present-moment-senses-practice', 'Present-Moment Senses Practice', 'act'::resource_kind, 'A brief five-senses noticing exercise to anchor a client in the current moment.', 'Give a client a portable way to step out of their head and into the room.', array['Adults', 'Teens', 'Children']::text[], 'Five minutes', 'This is a simple noticing practice rather than a way to make discomfort disappear; a client who expects to feel calm afterward may be disappointed and disengage. Frame it instead as a way to widen attention beyond whatever thought has been looping, one sense at a time, without judging what is noticed. It travels well: a waiting room, a car, a hallway before a hard meeting.', '[{"id": "f0", "type": "textarea", "label": "Something I can see right now"}, {"id": "f1", "type": "textarea", "label": "Something I can hear right now"}, {"id": "f2", "type": "textarea", "label": "Something I can feel touching my skin right now"}, {"id": "f3", "type": "textarea", "label": "Something I can smell right now"}, {"id": "f4", "type": "textarea", "label": "What shifted, if anything, after noticing all four"}]'::jsonb, array['mindfulness', 'core ACT', 'grounding']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('unwelcome-guest-metaphor', 'Unwelcome Guest Metaphor', 'act'::resource_kind, 'Uses the image of an uninvited houseguest to practice making room for a difficult feeling.', 'Help a client stop spending energy trying to evict a feeling that keeps coming back.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to picture the feeling as a houseguest who showed up without an invitation and will not be argued out the door. Fighting the guest, or pretending they are not there, tends to make the visit longer and louder. Practicing instead setting them a chair and going on with the evening gives the client language for acceptance that does not require liking the feeling.', '[{"id": "f0", "type": "textarea", "label": "The feeling I''ve been trying hardest to get rid of"}, {"id": "f1", "type": "textarea", "label": "What I usually do to try to evict it"}, {"id": "f2", "type": "textarea", "label": "What happens when I do that"}, {"id": "f3", "type": "textarea", "label": "What it might look like to set this feeling a chair instead"}, {"id": "f4", "type": "textarea", "label": "What I could still do with the guest in the room"}]'::jsonb, array['metaphor', 'acceptance', 'willingness']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('committed-action-obstacle-map', 'Committed Action Obstacle Map', 'act'::resource_kind, 'Maps the internal and external obstacles standing between a client and a values-based step.', 'Help a client plan around obstacles instead of being surprised by them.', array['Adults', 'Teens']::text[], '20 minutes', 'A values-based goal often stalls at the first obstacle because the client had not planned for it as a normal part of the path rather than a sign to stop. Naming the likely internal obstacles, a thought, a feeling, an urge to quit, next to the external ones gives the client a map instead of a surprise, and a line for what they will do when each one shows up.', '[{"id": "f0", "type": "textarea", "label": "The values-based step I want to take"}, {"id": "f1", "type": "textarea", "label": "An internal obstacle likely to show up, a thought or feeling"}, {"id": "f2", "type": "textarea", "label": "What I''ll do when it shows up"}, {"id": "f3", "type": "textarea", "label": "An external obstacle likely to show up"}, {"id": "f4", "type": "textarea", "label": "What I''ll do when that shows up"}, {"id": "f5", "type": "textarea", "label": "The very next small step, regardless of obstacles"}]'::jsonb, array['committed action', 'values', 'planning']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('thoughts-on-a-cloud-practice', 'Thoughts on a Cloud Practice', 'act'::resource_kind, 'A brief defusion exercise picturing thoughts drifting past like clouds rather than facts.', 'Give a client practice watching a thought instead of being pulled into it.', array['Adults', 'Teens', 'Children']::text[], 'Five minutes', 'Ask the client to notice a thought, place it on an imagined cloud, and watch it drift rather than chase it or push it away. The point is not to empty the mind but to practice the small shift from being inside a thought to watching it pass. Some clients find it easier with eyes open, tracking real clouds or ceiling tiles as the visual anchor.', '[{"id": "f0", "type": "textarea", "label": "A thought that''s been looping today"}, {"id": "f1", "type": "textarea", "label": "What it felt like to place it on the cloud and watch it drift"}, {"id": "f2", "type": "textarea", "label": "A thought that was hard to let drift"}, {"id": "f3", "type": "textarea", "label": "What I noticed in my body during the practice"}]'::jsonb, array['defusion', 'mindfulness', 'core ACT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('emotion-regulation-skills-menu', 'Emotion Regulation Skills Menu', 'dbt'::resource_kind, 'A personalized menu of go-to emotion regulation skills sorted by how much time they take.', 'Give a client a quick-reference list instead of trying to recall skills under stress.', array['Adults', 'Teens']::text[], '20 minutes to build, then ongoing', 'Under strong emotion, most clients cannot recall a skill they have not already written down somewhere accessible. Building the menu together in session, sorted into skills that take a minute, five minutes and twenty minutes, means the client has already done the thinking before they need it. Revisit the menu every few sessions; skills that sounded good on paper sometimes never get used.', '[{"id": "f0", "type": "textarea", "label": "A one-minute skill I can use almost anywhere"}, {"id": "f1", "type": "textarea", "label": "A five-minute skill for when I have a short break"}, {"id": "f2", "type": "textarea", "label": "A twenty-minute skill for when I have more space"}, {"id": "f3", "type": "textarea", "label": "Where I''ll keep this list so I can find it under stress"}]'::jsonb, array['emotion regulation', 'skills', 'planning']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('one-mindfully-in-the-moment-practice', 'One-Mindfully in the Moment Practice', 'dbt'::resource_kind, 'Practices doing one thing at a time with full attention, the one-mindfully mindfulness skill.', 'Reduce the split attention that keeps a client half-present in daily tasks.', array['Adults', 'Teens']::text[], '10 minutes', 'Pick one routine task, washing a dish, walking to the car, and practice giving it full attention instead of the usual multitasking. Clients often notice how quickly the mind wanders back to planning or replaying; the skill is in noticing the wander and returning, not preventing it. Building this in low-stakes moments makes it more available during a harder one.', '[{"id": "f0", "type": "textarea", "label": "The task I chose to practice on"}, {"id": "f1", "type": "textarea", "label": "How many times I noticed my mind wander"}, {"id": "f2", "type": "textarea", "label": "What it wandered to"}, {"id": "f3", "type": "textarea", "label": "What doing the task fully felt like compared to usual"}]'::jsonb, array['mindfulness', 'skills']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('turning-the-mind-practice', 'Turning the Mind Practice', 'dbt'::resource_kind, 'Practices the repeated choice to turn toward acceptance rather than fighting reality.', 'Help a client see acceptance as a decision made again and again, not a one-time feat.', array['Adults', 'Teens']::text[], '10 minutes', 'Turning the mind is choosing, in each moment, to face reality as it is rather than as the client wishes it were; it is not agreeing that a situation is fair or good. Clients often expect one big decision to settle it, then feel like they have failed when the fight comes back. Framing it as a fork in the road the client returns to, and chooses again, sets a more realistic expectation.', '[{"id": "f0", "type": "textarea", "label": "The reality I keep fighting against"}, {"id": "f1", "type": "textarea", "label": "What fighting it usually costs me"}, {"id": "f2", "type": "textarea", "label": "What turning toward it, just for now, might look like"}, {"id": "f3", "type": "textarea", "label": "A moment today I could practice turning the mind"}]'::jsonb, array['acceptance', 'mindfulness']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('interpersonal-effectiveness-warm-up-script', 'Interpersonal Effectiveness Warm-Up Script', 'dbt'::resource_kind, 'A short, low-stakes script for practicing an interpersonal effectiveness skill before it is needed for real.', 'Build fluency with an assertive script before a client needs it under pressure.', array['Adults', 'Teens']::text[], '15 minutes', 'Skills that sound clear on paper often disappear under real pressure because the client has never said the words out loud. Picking a low-stakes upcoming interaction, returning an item, asking a coworker a small favor, and rehearsing the actual sentences in session builds the muscle memory before a higher-stakes conversation needs it.', '[{"id": "f0", "type": "textarea", "label": "A low-stakes interaction coming up this week"}, {"id": "f1", "type": "textarea", "label": "What I want to ask for or say"}, {"id": "f2", "type": "textarea", "label": "The exact opening line I''ll use"}, {"id": "f3", "type": "textarea", "label": "How I''ll stay steady if the other person pushes back"}]'::jsonb, array['interpersonal effectiveness', 'communication', 'skills']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('distress-tolerance-skills-menu', 'Distress Tolerance Skills Menu', 'dbt'::resource_kind, 'A personalized list of distress tolerance skills a client can reach for in an overwhelming moment.', 'Give a client a ready reference for getting through intense distress without making it worse.', array['Adults', 'Teens']::text[], '20 minutes to build, then ongoing', 'Distress tolerance skills exist to get a client through an intense moment, not to fix the problem underneath it. Building a short, personalized list in session, ranked by what has actually worked before, means the client is not inventing a plan while already overwhelmed. Keep it somewhere physically accessible; a list saved only in memory tends to disappear exactly when it is needed.', '[{"id": "f0", "type": "textarea", "label": "A distress tolerance skill that''s worked for me before"}, {"id": "f1", "type": "textarea", "label": "A second skill I want to try"}, {"id": "f2", "type": "textarea", "label": "Where I''ll keep this list"}, {"id": "f3", "type": "textarea", "label": "A recent moment this list would have helped"}]'::jsonb, array['distress tolerance', 'skills', 'planning']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('shared-calendar-sync-meeting', 'Shared Calendar Sync Meeting', 'couples'::resource_kind, 'A short weekly meeting structure for keeping two schedules and responsibilities visible to both partners.', 'Reduce the friction that comes from one partner tracking everything alone.', array['Couples']::text[], '15 minutes weekly', 'Invisible logistical labor, remembering appointments, deadlines, whose turn it is, tends to fall on one partner by default and quietly breeds resentment. A short standing meeting where both partners bring their calendars and divide the coming week''s load out loud makes the labor visible and shared rather than assumed. Keep it brief and practical; save the emotional conversations for another time.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what''s on my plate this week"}, {"id": "f1", "type": "textarea", "label": "Partner B: what''s on my plate this week"}, {"id": "f2", "type": "textarea", "label": "What we''re splitting and how"}, {"id": "f3", "type": "textarea", "label": "One thing that fell through the cracks last week and why"}]'::jsonb, array['routines', 'communication', 'couples']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('conflict-cool-down-signal-system', 'Conflict Cool-Down Signal System', 'couples'::resource_kind, 'Sets up a shared, agreed-on signal for either partner to call a pause during an escalating conflict.', 'Give both partners a way to interrupt escalation before it does damage.', array['Couples']::text[], '15 minutes', 'Once a conflict is escalating, either partner trying to reason their way out often makes it worse. Agreeing in advance, outside of conflict, on a specific word or gesture either partner can use to call a pause, and what happens during the pause, turns a heated moment into something both partners already have a plan for. The signal only works if both partners agreed to honor it before it was needed.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a moment I wished we''d had a way to pause"}, {"id": "f1", "type": "textarea", "label": "Partner B: a moment I wished we''d had a way to pause"}, {"id": "f2", "type": "textarea", "label": "The signal we''re agreeing on"}, {"id": "f3", "type": "textarea", "label": "What each of us will do during the pause"}, {"id": "f4", "type": "textarea", "label": "How we''ll come back together afterward"}]'::jsonb, array['conflict', 'de-escalation', 'couples']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('vulnerability-sharing-circle', 'Vulnerability Sharing Circle', 'couples'::resource_kind, 'A structured turn-taking exercise for sharing something each partner rarely says out loud.', 'Deepen intimacy by practicing vulnerability in a low-risk, structured format.', array['Couples']::text[], '30 minutes', 'Vulnerability is easier to practice with structure than to ask for cold. Each partner takes a turn sharing something true and rarely spoken, a worry, a hope, a regret, while the other partner only listens and reflects back what they heard before responding. Keep the prompts open enough that either partner can choose how deep to go.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something true I rarely say out loud"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I heard, reflected back"}, {"id": "f2", "type": "textarea", "label": "Partner B: something true I rarely say out loud"}, {"id": "f3", "type": "textarea", "label": "Partner A: what I heard, reflected back"}, {"id": "f4", "type": "textarea", "label": "What it felt like to be the one listening"}]'::jsonb, array['intimacy', 'communication', 'couples']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('financial-values-alignment-sheet', 'Financial Values Alignment Sheet', 'couples'::resource_kind, 'Compares each partner''s beliefs about money to find where they align and where they clash.', 'Surface the values behind money disagreements instead of arguing about the numbers alone.', array['Couples']::text[], '25 minutes', 'Money conflict is often a values conflict wearing a budget''s clothing: one partner''s security is another''s restriction, one''s generosity is another''s risk. Having each partner name what money represents to them, separately, before comparing notes, usually explains a recurring argument better than any spreadsheet does. This works best as a starting conversation, not a one-time fix.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what money represents to me, safety, freedom, status, or something else"}, {"id": "f1", "type": "textarea", "label": "Partner B: what money represents to me"}, {"id": "f2", "type": "textarea", "label": "Where our beliefs line up"}, {"id": "f3", "type": "textarea", "label": "Where they clash"}, {"id": "f4", "type": "textarea", "label": "One small agreement we could try this month"}]'::jsonb, array['money', 'values', 'couples']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('long-distance-connection-planner', 'Long-Distance Connection Planner', 'couples'::resource_kind, 'Plans concrete ways to maintain connection across distance or opposite schedules.', 'Give a couple a deliberate structure for staying connected when time together is limited.', array['Couples']::text[], '20 minutes', 'Distance or mismatched schedules do not have to mean drifting, but they do mean connection needs planning instead of happening by default. Naming a few small, repeatable rituals, a call at a set time, a shared show, a running text thread, gives the relationship something to lean on between the times they are together. Revisit it when the schedule changes.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what makes me feel connected even at a distance"}, {"id": "f1", "type": "textarea", "label": "Partner B: what makes me feel connected even at a distance"}, {"id": "f2", "type": "textarea", "label": "One ritual we''ll try this week"}, {"id": "f3", "type": "textarea", "label": "How we''ll handle it if one of us misses it"}]'::jsonb, array['connection', 'routines', 'couples']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('kindness-chain-craft', 'Kindness Chain Craft', 'kids'::resource_kind, 'A child builds a paper chain, one link for each small act of kindness noticed or done.', 'Help a child build a visible, hands-on habit of noticing kindness.', array['Children']::text[], '10 minutes daily', 'The parent keeps a stack of paper strips handy, and each day the child adds a link for a kind act they did or noticed, from either direction. The chain becomes a visible, growing record that does not require the child to talk about feelings if they are not ready to; the parent can ask about a link now and then rather than every day.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I did today"}, {"id": "f1", "type": "textarea", "label": "A kind thing someone did for me"}, {"id": "f2", "type": "textarea", "label": "How the chain looks this week"}, {"id": "f3", "type": "textarea", "label": "Who I want to be kind to tomorrow"}]'::jsonb, array['kindness', 'children', 'art']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('team-family-chore-chart', 'Team Family Chore Chart', 'kids'::resource_kind, 'A visual chart where a child picks and tracks age-appropriate chores as part of the household team.', 'Build a child''s sense of contribution and follow-through with a concrete, visible system.', array['Children']::text[], 'Ongoing, five minutes daily', 'The parent and child pick a short list of age-appropriate tasks together, then the child marks each one off as it is done, ideally with a sticker or check rather than a grade. Keep the tone collaborative rather than transactional; the point is a felt sense of contributing to the household, not a reward economy. Adjust the list together every few weeks.', '[{"id": "f0", "type": "textarea", "label": "The chores I picked for this week"}, {"id": "f1", "type": "textarea", "label": "Which ones I finished today"}, {"id": "f2", "type": "textarea", "label": "One I found hardest and why"}, {"id": "f3", "type": "textarea", "label": "How I felt when I finished the list"}]'::jsonb, array['parenting', 'behavioral', 'routines']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('morning-mood-check-wheel', 'Morning Mood Check Wheel', 'kids'::resource_kind, 'A spinning wheel a child turns each morning to name how they''re arriving to the day.', 'Build a child''s early vocabulary for naming feelings before the day gets going.', array['Children']::text[], 'Five minutes daily', 'The child decorates and turns a simple paper wheel with faces or colors each morning, landing on however they are feeling that day. The parent''s job is to receive the answer without trying to fix or talk the child out of it, just to acknowledge it and note anything that might need extra patience that day. Over a few weeks, patterns tied to certain days or events often become visible.', '[{"id": "f0", "type": "textarea", "label": "What my wheel landed on this morning"}, {"id": "f1", "type": "textarea", "label": "One word for why I feel that way"}, {"id": "f2", "type": "textarea", "label": "Something that might help today"}, {"id": "f3", "type": "textarea", "label": "How my wheel felt different from yesterday''s"}]'::jsonb, array['emotion identification', 'children', 'routines']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('gratitude-garden-craft', 'Gratitude Garden Craft', 'kids'::resource_kind, 'A child adds a paper flower to a growing garden for each thing they''re grateful for.', 'Build a child''s habit of noticing good things with a hands-on, growing visual.', array['Children']::text[], '10 minutes daily', 'The parent keeps a poster or paper garden bed on the wall, and the child adds a decorated paper flower each day naming something they are grateful for, however small. The visible growth of the garden over weeks does more of the work than the individual entries; let the child choose colors and decorations freely rather than steering the content.', '[{"id": "f0", "type": "textarea", "label": "What flower I''m adding today"}, {"id": "f1", "type": "textarea", "label": "Why I picked that thing"}, {"id": "f2", "type": "textarea", "label": "How many flowers are in my garden now"}, {"id": "f3", "type": "textarea", "label": "My favorite flower so far and why"}]'::jsonb, array['gratitude', 'children', 'art']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('new-sibling-adjustment-storybook', 'New Sibling Adjustment Storybook', 'kids'::resource_kind, 'A child builds a simple illustrated storybook about becoming a big sibling.', 'Give a child a hands-on way to process the changes a new sibling brings.', array['Children']::text[], '20 minutes across a few sessions', 'A new baby reshapes an older child''s routines and attention even in a loving household, and a storybook the child controls gives them somewhere to put mixed feelings without needing the words for them yet. The parent helps with the pages but lets the child choose what happens in the story, including a page for a hard feeling if one comes up; that page deserves the same warm reception as any other.', '[{"id": "f0", "type": "textarea", "label": "The title of my storybook"}, {"id": "f1", "type": "textarea", "label": "A page about what changed at home"}, {"id": "f2", "type": "textarea", "label": "A page about a feeling I''ve had, even a hard one"}, {"id": "f3", "type": "textarea", "label": "A page about something I like about being a big sibling"}, {"id": "f4", "type": "textarea", "label": "How I want the story to end"}]'::jsonb, array['transitions', 'children', 'family']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('story-chain-circle-game', 'Story Chain Circle Game', 'game'::resource_kind, 'A group builds one story together, each person adding a sentence in turn.', 'Build group cohesion and flexible thinking through shared, low-stakes creativity.', array['Groups', 'Teens']::text[], '20 minutes', 'Sitting or standing in a circle, each group member adds one sentence to a story that has no set direction, building on whatever the last person said rather than steering it themselves. The rule is no vetoing another player''s addition, only building on it, which practices flexibility and tolerating a story that does not go the way any one person planned. Debrief by asking what was hard about not being in control of the story.', '[{"id": "f0", "type": "textarea", "label": "A sentence I contributed that I liked"}, {"id": "f1", "type": "textarea", "label": "A moment the story went somewhere I didn''t expect"}, {"id": "f2", "type": "textarea", "label": "How it felt to build on someone else''s idea instead of my own"}, {"id": "f3", "type": "textarea", "label": "What this reminds me of in real life"}]'::jsonb, array['group', 'play', 'communication']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('would-you-rather-boundaries-edition', 'Would You Rather: Boundaries Edition', 'game'::resource_kind, 'A card game of paired scenarios that gets a group talking about setting limits.', 'Open group discussion about boundaries through low-stakes, playful choices.', array['Groups', 'Teens']::text[], '20 minutes', 'Players take turns drawing a card with two boundary-related scenarios, would you rather tell a friend no or do something you don''t want to do, and picking one, then briefly saying why. The paired-choice format lowers the stakes of talking about a topic that can otherwise feel exposing, and the debrief afterward is where the real conversation about each player''s own boundaries usually opens up.', '[{"id": "f0", "type": "textarea", "label": "A card I drew and what I picked"}, {"id": "f1", "type": "textarea", "label": "Why I picked that one"}, {"id": "f2", "type": "textarea", "label": "A scenario I found genuinely hard to choose between"}, {"id": "f3", "type": "textarea", "label": "One boundary of my own this game reminded me of"}]'::jsonb, array['boundaries', 'group', 'play']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('pass-the-feeling-ball', 'Pass the Feeling Ball', 'game'::resource_kind, 'A group passes a ball around, naming a feeling and a time they felt it before passing it on.', 'Build group comfort naming a range of feelings out loud.', array['Groups', 'Children', 'Teens']::text[], '15 minutes', 'Sitting in a circle, each player holds the ball, names a feeling, a brief moment they felt it, and passes it on to the next person. No feeling can repeat once it has been said, which gently pushes the group past the same few words toward a wider feelings vocabulary. Keep the shared moments brief and let any player pass on details if they would rather not elaborate.', '[{"id": "f0", "type": "textarea", "label": "The feeling I named"}, {"id": "f1", "type": "textarea", "label": "A brief moment I felt it"}, {"id": "f2", "type": "textarea", "label": "A feeling someone else named that I don''t use often"}, {"id": "f3", "type": "textarea", "label": "How it felt to hear the group''s different feelings"}]'::jsonb, array['emotion identification', 'group', 'play']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('values-tug-of-war-game', 'Values Tug of War Game', 'game'::resource_kind, 'A verbal tug-of-war where two sides argue for competing values in a shared scenario.', 'Make the tension between competing values felt and discussable rather than abstract.', array['Groups', 'Teens']::text[], '20 minutes', 'Give the group a scenario with two values pulling in different directions, honesty versus loyalty, ambition versus rest, and split into two sides to argue for each value before swapping. Making the pull between two genuinely good things visible, rather than framing one side as simply wrong, helps players recognize the same tension in their own decisions. Debrief on which value usually wins for each player and why.', '[{"id": "f0", "type": "textarea", "label": "The scenario and two values in tension"}, {"id": "f1", "type": "textarea", "label": "The side I argued and my strongest point"}, {"id": "f2", "type": "textarea", "label": "The strongest point I heard from the other side"}, {"id": "f3", "type": "textarea", "label": "Which value tends to win for me in real life"}]'::jsonb, array['values', 'group', 'play']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('circle-of-support-web-game', 'Circle of Support Web Game', 'game'::resource_kind, 'A group passes a ball of yarn to build a visible web representing their support connections.', 'Make a group''s sense of connection and support visible and felt.', array['Groups', 'Teens']::text[], '20 minutes', 'Holding one end of a ball of yarn, a player names someone who supports them and tosses the ball to another player, who does the same, building a visible web across the circle. The web makes an otherwise abstract idea, that support exists even when it does not feel that way, into something the group can see and hold. Debrief by asking what it felt like to be named by someone else.', '[{"id": "f0", "type": "textarea", "label": "Someone I named as support and why"}, {"id": "f1", "type": "textarea", "label": "What it felt like when someone named me"}, {"id": "f2", "type": "textarea", "label": "A gap in the web I noticed for myself"}, {"id": "f3", "type": "textarea", "label": "One strand of the web I want to strengthen"}]'::jsonb, array['connection', 'group', 'play']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('comfort-corner-building-craft', 'Comfort Corner Building Craft', 'kids'::resource_kind, 'A child builds a physical calm corner with objects that help them feel safe and settled.', 'Give a child a concrete, physical place to return to when they feel unsettled.', array['Children']::text[], '30 minutes to build, then ongoing', 'The parent and child choose a small corner or box and fill it together with a few comforting objects, a soft blanket, a favorite toy, a drawing, that the child picks themselves. This stays a resource for calming and safety, not a place to revisit what happened; keep the conversation on what helps the child feel settled now. If a child discloses anything concerning while building it, the clinician''s reporting duties apply as they would in any session.', '[{"id": "f0", "type": "textarea", "label": "The corner or box I picked"}, {"id": "f1", "type": "textarea", "label": "Objects I put in it and why"}, {"id": "f2", "type": "textarea", "label": "How I feel when I go there"}, {"id": "f3", "type": "textarea", "label": "Who helped me build it"}]'::jsonb, array['PTSD and trauma', 'safety', 'children']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('grounding-skills-card-draw-game', 'Grounding Skills Card Draw Game', 'game'::resource_kind, 'A group or individual draws cards and practices a different grounding skill on each turn.', 'Build familiarity with a range of grounding skills through low-stakes repetition.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'Each card names a different grounding skill, naming five things seen, pressing feet into the floor, holding something cold, and the player practices it for a minute before rating how settled they felt out of ten. Playing it outside of a distressed moment builds familiarity so the skill is easier to reach for when it is actually needed. Keep this game to grounding skills only; it is not a place to process what happened.', '[{"id": "f0", "type": "textarea", "label": "A skill I drew and how it felt"}, {"id": "f1", "type": "textarea", "label": "How settled I felt after, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "The skill that worked best for me today"}, {"id": "f3", "type": "textarea", "label": "Where I''ll remember to use it this week"}]'::jsonb, array['PTSD and trauma', 'grounding', 'coping skills']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('pacing-plan-for-hard-days', 'Pacing Plan for Hard Days', 'worksheet'::resource_kind, 'Helps a client plan how to pace activity and rest on days when trauma symptoms are stronger.', 'Give a client a plan for getting through a harder day without pushing past their capacity.', array['Adults', 'Teens']::text[], '20 minutes', 'Some days carry more activation than others, and pushing through on those days the same way a client would on a calmer one often backfires. Naming early signs that today is a harder day, and a short list of adjustments, fewer commitments, more breaks, a support person on call, turns a reactive scramble into something planned in advance. Review and adjust the plan after it has been tried once.', '[{"id": "f0", "type": "textarea", "label": "An early sign today is a harder day"}, {"id": "f1", "type": "textarea", "label": "One commitment I could lighten or postpone"}, {"id": "f2", "type": "textarea", "label": "A support person I could reach out to"}, {"id": "f3", "type": "textarea", "label": "A pacing adjustment that''s worked before"}, {"id": "f4", "type": "textarea", "label": "What I''ll do for myself once the harder day has passed"}]'::jsonb, array['PTSD and trauma', 'pacing', 'self-monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('present-day-evidence-scan', 'Present-Day Evidence Scan', 'cbt'::resource_kind, 'A brief scan for current, present-day evidence of safety when a trauma reminder triggers alarm.', 'Help a client''s nervous system catch up to the fact that the threat has passed.', array['Adults', 'Teens']::text[], '10 minutes', 'A trauma reminder can trigger a full alarm response even when nothing in the current moment is actually dangerous. Scanning the room for concrete, present-day evidence, the date, the people nearby, the locked door, gives the client''s thinking mind something to offer the alarmed body. This works alongside grounding rather than instead of it, and is meant for the present moment, not for reviewing the past event.', '[{"id": "f0", "type": "textarea", "label": "What triggered the alarm feeling"}, {"id": "f1", "type": "textarea", "label": "The year and place I actually am right now"}, {"id": "f2", "type": "textarea", "label": "Someone or something nearby that''s safe"}, {"id": "f3", "type": "textarea", "label": "How my alarm level changed after the scan, 0 to 10"}]'::jsonb, array['PTSD and trauma', 'grounding', 'core CBT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('tipp-for-trauma-reminders', 'TIPP for Trauma Reminders', 'dbt'::resource_kind, 'Applies the TIPP distress tolerance skill to the spike that follows a trauma reminder.', 'Give a client a fast, body-based way to bring down an activation spike.', array['Adults', 'Teens']::text[], 'Five minutes', 'When a reminder sends the body into a full activation spike, thinking-based skills are often out of reach until the body calms down first. TIPP, temperature, intense exercise, paced breathing, paired muscle relaxation, works on the body directly and can bring the spike down enough for other skills to become usable again. Rehearse which TIPP option the client has access to before it is needed.', '[{"id": "f0", "type": "textarea", "label": "The TIPP option most available to me, cold water, movement, breathing, or muscle relaxation"}, {"id": "f1", "type": "textarea", "label": "How activated I felt before, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "How activated I felt after, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Where I''ll keep what I need for this skill accessible"}]'::jsonb, array['PTSD and trauma', 'distress tolerance', 'regulation']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('supporting-without-reassuring-sheet', 'Supporting Without Reassuring Sheet', 'couples'::resource_kind, 'Helps a couple find ways to support anxiety that don''t feed a reassurance-seeking cycle.', 'Give both partners a plan for support that doesn''t accidentally maintain the anxiety.', array['Couples']::text[], '20 minutes', 'A partner''s constant reassurance often feels like the kind thing to do but can quietly keep an anxious cycle going, since the relief never lasts and the question comes back. Naming a few alternative responses together, sitting with the worry instead of answering it, a hug instead of a fact, a shared decision on how many times to answer the same question, gives both partners a plan they have agreed on rather than an in-the-moment guess.', '[{"id": "f0", "type": "textarea", "label": "Anxious partner: what reassurance I tend to ask for"}, {"id": "f1", "type": "textarea", "label": "Supporting partner: what I usually say or do"}, {"id": "f2", "type": "textarea", "label": "What tends to happen after the reassurance wears off"}, {"id": "f3", "type": "textarea", "label": "An alternative response we want to try"}, {"id": "f4", "type": "textarea", "label": "How the anxious partner will signal what they actually need in the moment"}]'::jsonb, array['anxiety', 'support', 'couples']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('what-if-spiral-interrupter', 'What-If Spiral Interrupter', 'worksheet'::resource_kind, 'Catches a chain of what-if worries and finds the first link where the chain could be interrupted.', 'Help a client interrupt a worry spiral earlier instead of riding it to the end.', array['Adults', 'Teens']::text[], '15 minutes', 'A what-if spiral rarely announces itself; by the time a client notices, they are several links deep into an imagined worst case. Writing out the whole chain after the fact, from the first what-if to the last, shows the client where the spiral usually starts, which is often a much smaller and more manageable thought than where it ends up. Practice catching the chain at that earlier link next time.', '[{"id": "f0", "type": "textarea", "label": "The first what-if in the chain"}, {"id": "f1", "type": "textarea", "label": "The next few links, one after another"}, {"id": "f2", "type": "textarea", "label": "Where the chain ended up"}, {"id": "f3", "type": "textarea", "label": "Which link, in hindsight, would have been the easiest to interrupt"}, {"id": "f4", "type": "textarea", "label": "What I could do or think at that link instead"}]'::jsonb, array['anxiety', 'worry', 'self-monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('anxious-body-signals-log', 'Anxious Body Signals Log', 'dbt'::resource_kind, 'Tracks the earliest physical signs anxiety is building, before the worry thoughts catch up.', 'Help a client catch anxiety earlier by tracking body signals instead of waiting for the thoughts.', array['Adults', 'Teens']::text[], 'Ongoing, brief entries', 'The body often signals rising anxiety, a tight chest, a clenched jaw, restless legs, before the client consciously registers worry thoughts. Logging these signals across a few days builds a personal early-warning list, so a regulation skill can be used earlier, when it is easier for the body to settle, rather than waiting until the worry is already in full swing.', '[{"id": "f0", "type": "textarea", "label": "A physical signal I noticed today"}, {"id": "f1", "type": "textarea", "label": "What was happening around that time"}, {"id": "f2", "type": "textarea", "label": "How high the anxiety got, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "A skill I used or could have used at that signal"}]'::jsonb, array['anxiety', 'body awareness', 'self-monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('worry-weather-forecast-craft', 'Worry Weather Forecast Craft', 'kids'::resource_kind, 'A child draws a daily weather forecast for their worries, from clear skies to storms.', 'Give a child a playful, external way to communicate how big their worry feels.', array['Children']::text[], '10 minutes daily', 'The child draws a small weather forecast each day, sunny, cloudy, stormy, to represent how big their worries feel, which sidesteps needing the words to explain a feeling that can be hard to name directly. The parent''s job is to notice the forecast without demanding an explanation for every stormy day; over time, patterns tied to certain days or events often become visible.', '[{"id": "f0", "type": "textarea", "label": "Today''s worry weather forecast"}, {"id": "f1", "type": "textarea", "label": "What might have made the weather that way"}, {"id": "f2", "type": "textarea", "label": "What could help turn a storm into clearer skies"}, {"id": "f3", "type": "textarea", "label": "Yesterday''s forecast, for comparison"}]'::jsonb, array['anxiety', 'children', 'self-monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('worry-toss-bean-bag-game', 'Worry Toss Bean Bag Game', 'game'::resource_kind, 'Players toss a bean bag into labeled bins representing different-sized worries and discuss where their own worries land.', 'Build a playful, shared vocabulary for sorting the size of a worry.', array['Groups', 'Children', 'Teens']::text[], '15 minutes', 'Set up bins labeled small, medium and big worry, and each player tosses a bean bag, names a worry that fits that size, and briefly says why. The physical sorting makes an abstract skill, judging how big a worry actually is, into something concrete and shared, and hearing other players sort their own worries often helps a player recalibrate their own.', '[{"id": "f0", "type": "textarea", "label": "A worry I sorted and which bin it landed in"}, {"id": "f1", "type": "textarea", "label": "Why I sorted it that way"}, {"id": "f2", "type": "textarea", "label": "A worry from someone else that surprised me"}, {"id": "f3", "type": "textarea", "label": "A worry of mine that might belong in a smaller bin than I thought"}]'::jsonb, array['anxiety', 'group', 'play']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('energy-cost-ledger', 'Energy Cost Ledger', 'cbt'::resource_kind, 'Tracks which daily activities cost energy and which return it, to guide low-energy planning.', 'Help a client plan a day around their actual energy rather than an idealized one.', array['Adults']::text[], 'Ongoing, brief daily entries', 'Low mood often narrows a client''s sense of what is worth doing to almost nothing, which makes planning feel pointless. Logging a handful of daily activities as either costing or returning energy, regardless of how small, builds a personal map the client can use to balance a low-energy day instead of guessing. The point is not to avoid every costly activity, just to know the trade before making it.', '[{"id": "f0", "type": "textarea", "label": "An activity from today that cost me energy"}, {"id": "f1", "type": "textarea", "label": "An activity from today that gave some back"}, {"id": "f2", "type": "textarea", "label": "My overall energy level today, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "One low-cost, energy-returning activity I could plan for tomorrow"}]'::jsonb, array['depression', 'monitoring', 'core CBT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('small-values-step-finder', 'Small Values Step Finder', 'act'::resource_kind, 'Finds the smallest possible step toward a value when energy and motivation are low.', 'Keep a client moving toward what matters even when a full step feels out of reach.', array['Adults', 'Teens']::text[], '15 minutes', 'Waiting for motivation before acting rarely works with low mood, since motivation tends to follow action rather than precede it. Naming a value, then scaling the step down until it feels almost too small to count, a two-minute version of the task, gives the client something achievable today rather than an all-or-nothing goal that gets postponed again.', '[{"id": "f0", "type": "textarea", "label": "A value I want to move toward"}, {"id": "f1", "type": "textarea", "label": "What a full step toward it would look like"}, {"id": "f2", "type": "textarea", "label": "What a two-minute version of that step looks like"}, {"id": "f3", "type": "textarea", "label": "What I noticed after taking the small step"}]'::jsonb, array['depression', 'values', 'committed action']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('behavioral-activation-ladder-card', 'Behavioral Activation Ladder Card', 'dbt'::resource_kind, 'Ranks a short list of low-mood activities from easiest to hardest to attempt today.', 'Give a client an ordered starting point when everything feels equally impossible.', array['Adults', 'Teens']::text[], '15 minutes', 'When everything feels equally hard, a client often ends up doing nothing rather than choosing where to start. Ranking a short list of activities from easiest to hardest gives an ordered starting point; the goal on a low day is simply the next rung up, not the top of the ladder. Revisit the ranking often, since it shifts with mood.', '[{"id": "f0", "type": "textarea", "label": "The easiest activity on my list right now"}, {"id": "f1", "type": "textarea", "label": "The next rung up"}, {"id": "f2", "type": "textarea", "label": "The hardest activity on the list"}, {"id": "f3", "type": "textarea", "label": "Which rung I attempted today"}, {"id": "f4", "type": "textarea", "label": "What happened afterward"}]'::jsonb, array['depression', 'behavioral activation', 'planning']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('low-mood-day-check-in-script', 'Low-Mood Day Check-In Script', 'couples'::resource_kind, 'Gives a supporting partner a short script for checking in without pressuring or fixing.', 'Help a couple navigate a low-mood day without one partner over-functioning.', array['Couples']::text[], '15 minutes', 'A supporting partner''s instinct to fix or cheer up a low-mood day can land as pressure rather than help. Agreeing in advance on a short, low-demand check-in script, and what the depressed partner actually wants on those days, more company or more space, gives both partners something to fall back on instead of guessing in the moment.', '[{"id": "f0", "type": "textarea", "label": "Depressed partner: what actually helps on a low-mood day"}, {"id": "f1", "type": "textarea", "label": "Depressed partner: what doesn''t help, even if well-meant"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: the check-in script we''re agreeing on"}, {"id": "f3", "type": "textarea", "label": "How the depressed partner will signal which kind of day it is"}]'::jsonb, array['depression', 'support', 'couples']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('small-sparks-jar', 'Small Sparks Jar', 'kids'::resource_kind, 'A child collects tiny drawings of things that gave them even a small spark of interest.', 'Help a child notice small moments of interest without pressure to feel fully happy.', array['Children']::text[], 'Five minutes daily', 'The child adds a small drawing to the jar for anything that gave even a flicker of interest, not full happiness, which keeps the bar low enough to actually reach on a hard day. The parent''s role is to notice the jar filling without pushing for a bigger reaction than the child has; a slow week is worth naming too, without alarm.', '[{"id": "f0", "type": "textarea", "label": "Today''s small spark, drawn or described"}, {"id": "f1", "type": "textarea", "label": "How big the spark felt"}, {"id": "f2", "type": "textarea", "label": "How many drawings are in the jar now"}, {"id": "f3", "type": "textarea", "label": "A spark from earlier in the week I still remember"}]'::jsonb, array['depression', 'children', 'monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('focus-relay-race', 'Focus Relay Race', 'game'::resource_kind, 'A group relay game that breaks a task into short, timed bursts with movement breaks between.', 'Practice sustaining short bursts of focus with built-in movement as a reward.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Each round pairs a short, timed focus task, a quick puzzle or worksheet, with a burst of movement, a lap or a stretch relay, between rounds. Framing the movement as a built-in part of the game rather than a break earned by sitting still models a rhythm of focus and release that a client can later adapt on their own.', '[{"id": "f0", "type": "textarea", "label": "How long I stayed focused during a round"}, {"id": "f1", "type": "textarea", "label": "What helped me stay with the task"}, {"id": "f2", "type": "textarea", "label": "What pulled my attention away"}, {"id": "f3", "type": "textarea", "label": "How the movement break felt afterward"}]'::jsonb, array['ADHD', 'group', 'task initiation']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('what-matters-right-now-check', 'What Matters Right Now Check', 'act'::resource_kind, 'A brief check-in on which task actually connects to a client''s values before switching tasks.', 'Help a client choose the next task deliberately instead of chasing whatever feels urgent.', array['Adults', 'Teens']::text[], 'Five minutes', 'Attention often follows whatever feels most urgent or interesting in the moment, which can pull a client away from what actually matters to them. A brief pause before switching tasks, naming which option connects to a value and which is just noise, gives the client a moment of choice rather than autopilot. This works better as a quick habit than a long planning session.', '[{"id": "f0", "type": "textarea", "label": "The task pulling my attention right now"}, {"id": "f1", "type": "textarea", "label": "The task I was supposed to be doing"}, {"id": "f2", "type": "textarea", "label": "Which one connects to something I actually value"}, {"id": "f3", "type": "textarea", "label": "What I chose to do next"}]'::jsonb, array['ADHD', 'values', 'core ACT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('task-switching-cost-log', 'Task Switching Cost Log', 'cbt'::resource_kind, 'Tracks how much time and focus is lost each time a client switches tasks mid-stream.', 'Make the hidden cost of task-switching visible so a client can plan around it.', array['Adults', 'Teens']::text[], 'Ongoing, brief entries', 'Switching tasks feels free in the moment but usually costs real time re-orienting to whatever was interrupted. Logging a few switches across a day, what pulled attention away and how long it took to get back on track, makes an invisible cost visible, which often motivates small changes like closing tabs or setting a timer before a task even more than being told to focus does.', '[{"id": "f0", "type": "textarea", "label": "What I was doing before the switch"}, {"id": "f1", "type": "textarea", "label": "What pulled me away"}, {"id": "f2", "type": "textarea", "label": "How long it took me to get back on track"}, {"id": "f3", "type": "textarea", "label": "What might have prevented that switch"}]'::jsonb, array['ADHD', 'self-monitoring', 'core CBT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('task-reminder-without-nagging-agreement', 'Task Reminder Without Nagging Agreement', 'couples'::resource_kind, 'A couple agrees on a neutral way to remind each other about tasks that doesn''t feel like nagging.', 'Reduce the resentment cycle that builds around reminders and forgotten tasks.', array['Couples']::text[], '20 minutes', 'A reminder can land as nagging even when it is meant kindly, and the partner doing the reminding often feels unheard when it is dismissed. Agreeing together on a neutral format, a shared list, a specific phrase, a set time of day, takes the tone out of the reminder and puts the system in charge instead of either partner. Revisit the agreement if it stops working.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what a reminder usually sounds like from me"}, {"id": "f1", "type": "textarea", "label": "Partner B: how that reminder tends to land"}, {"id": "f2", "type": "textarea", "label": "The neutral reminder system we''re agreeing to try"}, {"id": "f3", "type": "textarea", "label": "What each of us will do if the system isn''t working"}]'::jsonb, array['ADHD', 'communication', 'couples']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('external-memory-system-setup-sheet', 'External Memory System Setup Sheet', 'worksheet'::resource_kind, 'Helps a client build an external system, not memory, to track tasks and deadlines.', 'Reduce reliance on memory alone by building a trusted external system.', array['Adults', 'Teens']::text[], '20 minutes', 'Relying on memory alone to track tasks sets a client up to feel like they are failing at something that is not really a memory problem at all. Choosing one place, a single app, a wall calendar, a notebook, and building the habit of writing everything there the moment it comes up takes the load off memory and puts it somewhere trustworthy and checkable.', '[{"id": "f0", "type": "textarea", "label": "The one system I''m choosing to trust"}, {"id": "f1", "type": "textarea", "label": "Where I''ll keep it so I actually see it"}, {"id": "f2", "type": "textarea", "label": "A task I almost forgot this week that belongs in it"}, {"id": "f3", "type": "textarea", "label": "When I''ll check the system each day"}]'::jsonb, array['ADHD', 'executive function', 'planning']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('supporting-recovery-without-policing-sheet', 'Supporting Recovery Without Policing Sheet', 'couples'::resource_kind, 'Helps a couple find a supportive role that doesn''t turn one partner into a monitor of the other''s substance use.', 'Give both partners a way to support recovery that doesn''t erode trust or autonomy.', array['Couples']::text[], '20 minutes', 'A supporting partner who takes on constant monitoring, checking, searching, questioning, often does it out of fear, but it tends to erode trust on both sides rather than reduce urges. Naming together what support actually looks like, and what crosses into policing, gives both partners a clearer, more sustainable role than vigilance alone.', '[{"id": "f0", "type": "textarea", "label": "Partner in recovery: what support actually helps"}, {"id": "f1", "type": "textarea", "label": "Partner in recovery: what feels like policing instead"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: what I''m afraid will happen if I step back from monitoring"}, {"id": "f3", "type": "textarea", "label": "A form of support we''re agreeing to try instead"}, {"id": "f4", "type": "textarea", "label": "How we''ll check in on how this is working"}]'::jsonb, array['addiction', 'support', 'couples']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('urge-wave-tracker-for-teens', 'Urge Wave Tracker for Teens', 'kids'::resource_kind, 'A teen tracks the rise and fall of an urge on a simple wave drawing, with a trusted adult checking in.', 'Help a teen see that an urge to use a substance rises and falls rather than lasting forever.', array['Teens']::text[], 'Five minutes per urge', 'The teen draws a simple wave shape each time an urge shows up, marking how strong it felt at the peak and how long it took to come back down, with a trusted adult checking in afterward rather than during. Seeing the wave shape across several entries helps a teen trust that an urge passes on its own, which is easier to believe on paper than in the moment.', '[{"id": "f0", "type": "textarea", "label": "What the urge was about"}, {"id": "f1", "type": "textarea", "label": "How strong it felt at the peak, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "How long it took to come back down"}, {"id": "f3", "type": "textarea", "label": "What I did while I waited it out"}, {"id": "f4", "type": "textarea", "label": "Who I checked in with afterward"}]'::jsonb, array['addiction', 'urges', 'self-monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('urge-surfing-with-tipp-combo-card', 'Urge Surfing With TIPP Combo Card', 'dbt'::resource_kind, 'Pairs the urge surfing skill with a TIPP option for when an urge feels too intense to simply observe.', 'Give a client a backup plan for when an urge is too intense to ride out through observation alone.', array['Adults', 'Teens']::text[], '10 minutes', 'Urge surfing works by observing the urge rise and fall rather than acting on it, but some urges arrive too intense for observation alone to hold. Pairing it with a fast body-based TIPP option, cold water, brief intense movement, gives the client a way to bring the intensity down first, then return to surfing the rest of the wave.', '[{"id": "f0", "type": "textarea", "label": "How intense the urge felt at first, 0 to 10"}, {"id": "f1", "type": "textarea", "label": "The TIPP option I used"}, {"id": "f2", "type": "textarea", "label": "How intense it felt after"}, {"id": "f3", "type": "textarea", "label": "What I noticed as the rest of the wave passed"}]'::jsonb, array['addiction', 'urges', 'distress tolerance']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('cravings-and-consequences-card-game', 'Cravings and Consequences Card Game', 'game'::resource_kind, 'A group card game matching common urge triggers to a range of coping responses.', 'Build quick recall of coping responses to common urge triggers through repetition.', array['Groups', 'Adults', 'Teens']::text[], '20 minutes', 'Players draw a trigger card, a stressful call, a certain place, a certain person, and match it to a coping response card from a shared pile, discussing whether the match would actually work for them. Playing it in a group normalizes that triggers are common and specific rather than a personal failing, and the discussion surfaces coping options a player might not have thought of alone.', '[{"id": "f0", "type": "textarea", "label": "A trigger card I drew"}, {"id": "f1", "type": "textarea", "label": "The coping response I matched to it"}, {"id": "f2", "type": "textarea", "label": "Whether that match would work for me and why"}, {"id": "f3", "type": "textarea", "label": "A coping response from another player I want to borrow"}]'::jsonb, array['addiction', 'urges', 'group']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('values-beyond-the-next-urge-practice', 'Values Beyond the Next Urge Practice', 'act'::resource_kind, 'Connects a client''s urge-surfing practice to a specific value they''re protecting by riding it out.', 'Give a client a reason to ride out an urge that''s bigger than willpower alone.', array['Adults', 'Teens']::text[], '10 minutes', 'Riding out an urge on willpower alone tends to run out; connecting the choice to a specific value, being present for a child, trusting oneself, keeping a job, gives the moment a reason that outlasts the urge itself. Naming the value before the urge hits, not during, means it is already available when the moment gets hard.', '[{"id": "f0", "type": "textarea", "label": "A value that matters more to me than giving into this urge"}, {"id": "f1", "type": "textarea", "label": "How riding out the urge protects that value"}, {"id": "f2", "type": "textarea", "label": "A recent moment I rode out an urge and what value was underneath it"}, {"id": "f3", "type": "textarea", "label": "Where I''ll keep this value in mind for next time"}]'::jsonb, array['addiction', 'values', 'core ACT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('anger-as-information-practice', 'Anger as Information Practice', 'act'::resource_kind, 'Reframes an anger episode as information about a boundary or value rather than a problem to suppress.', 'Help a client use anger as a signal instead of fighting or acting on it automatically.', array['Adults', 'Teens']::text[], '15 minutes', 'Anger often carries information, a crossed boundary, a violated value, that gets lost when the client either suppresses it or acts on it immediately. Slowing down to ask what the anger might be pointing to, separately from deciding what to do about it, gives the client room to respond deliberately instead of reactively. This is not about excusing harmful behavior, just about listening to the signal first.', '[{"id": "f0", "type": "textarea", "label": "A recent moment I felt angry"}, {"id": "f1", "type": "textarea", "label": "What boundary or value the anger might be pointing to"}, {"id": "f2", "type": "textarea", "label": "What I did in the moment"}, {"id": "f3", "type": "textarea", "label": "What a deliberate response, informed by that value, could look like next time"}]'::jsonb, array['anger management', 'values', 'core ACT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('anger-trigger-thought-log', 'Anger Trigger Thought Log', 'cbt'::resource_kind, 'Logs the specific thought that turns an irritation into full anger.', 'Help a client find the thought that escalates a moment from annoyed to angry.', array['Adults', 'Teens']::text[], 'Ongoing, brief entries', 'Between an irritating event and a full anger response sits a thought, often about fairness, disrespect or intention, that does the escalating. Logging that specific thought next to the event shows the client where their own interpretation, not just the event, is driving the intensity, which opens room to question whether the interpretation is the only possible one.', '[{"id": "f0", "type": "textarea", "label": "The event that irritated me"}, {"id": "f1", "type": "textarea", "label": "The thought that turned it into anger"}, {"id": "f2", "type": "textarea", "label": "How angry I got, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "A different way to read the same event"}]'::jsonb, array['anger management', 'thinking traps', 'core CBT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('anger-thermometer-trivia-challenge', 'Anger Thermometer Trivia Challenge', 'game'::resource_kind, 'A trivia-style group game testing knowledge of anger warning signs and cool-down skills.', 'Build quick, shared recall of anger warning signs and cool-down options.', array['Groups', 'Teens']::text[], '20 minutes', 'Teams answer trivia-style questions about physical warning signs of rising anger and matching cool-down skills, scoring points for correct answers and bonus points for sharing a real example from their own life. The competitive format keeps a topic that can feel heavy light enough to engage with, while the shared examples build a group''s collective toolkit.', '[{"id": "f0", "type": "textarea", "label": "A warning sign question I answered"}, {"id": "f1", "type": "textarea", "label": "A cool-down skill I learned from another player"}, {"id": "f2", "type": "textarea", "label": "A real example I shared"}, {"id": "f3", "type": "textarea", "label": "The cool-down skill I''m most likely to actually use"}]'::jsonb, array['anger management', 'group', 'play']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('fairness-filter-check', 'Fairness Filter Check', 'worksheet'::resource_kind, 'Checks whether an anger-triggering belief about fairness holds up against a second read of the situation.', 'Slow down a client''s fairness-based anger reaction long enough to check it.', array['Adults', 'Teens']::text[], '15 minutes', 'A lot of anger runs through a belief that something is unfair, which can be true and still benefit from a second look before acting on it. Writing out the fairness belief, then considering what the other person might say about the same situation, does not require agreeing with them, just widening the picture enough to choose a response rather than react on the first read.', '[{"id": "f0", "type": "textarea", "label": "What felt unfair about the situation"}, {"id": "f1", "type": "textarea", "label": "My fairness belief about it"}, {"id": "f2", "type": "textarea", "label": "What the other person might say about the same situation"}, {"id": "f3", "type": "textarea", "label": "How my anger shifted after considering their side"}, {"id": "f4", "type": "textarea", "label": "How I want to respond, now that I''ve widened the picture"}]'::jsonb, array['anger management', 'thinking traps', 'self-monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('anger-repair-timing-agreement', 'Anger Repair Timing Agreement', 'couples'::resource_kind, 'A couple agrees in advance on when it''s the right time to attempt repair after an angry moment.', 'Prevent repair attempts from backfiring by timing them to when both partners are ready.', array['Couples']::text[], '15 minutes', 'A repair attempt offered before a partner has cooled down can land as pressure and restart the conflict instead of ending it. Agreeing in advance on a rough signal for when each partner is ready, a specific amount of time, a physical cue, gives both partners permission to wait without it meaning the issue is being avoided.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I usually know I''m ready to repair"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I usually know I''m ready to repair"}, {"id": "f2", "type": "textarea", "label": "The signal we''re agreeing on for ''ready to talk''"}, {"id": "f3", "type": "textarea", "label": "What each of us will do while we wait for that signal"}]'::jsonb, array['anger management', 'repair', 'couples']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('uncertainty-tolerance-log', 'Uncertainty Tolerance Log', 'worksheet'::resource_kind, 'Tracks moments a client sat with uncertainty instead of performing a compulsion to resolve it.', 'Build a client''s evidence that uncertainty can be tolerated without a compulsion.', array['Adults', 'Teens']::text[], 'Ongoing, brief entries', 'The pull to resolve uncertainty through a compulsion is strong precisely because it works in the short term. Logging moments the client sat with not-knowing instead, even briefly, and what happened afterward, builds a personal record that uncertainty is survivable, which counts for more than being told so directly.', '[{"id": "f0", "type": "textarea", "label": "The uncertain thought or situation"}, {"id": "f1", "type": "textarea", "label": "The compulsion I felt pulled toward"}, {"id": "f2", "type": "textarea", "label": "How long I sat with the uncertainty instead"}, {"id": "f3", "type": "textarea", "label": "What actually happened afterward"}]'::jsonb, array['OCD', 'uncertainty', 'self-monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('delay-and-distract-skills-card', 'Delay and Distract Skills Card', 'dbt'::resource_kind, 'Pairs a short delay period with a distress tolerance skill to ride out a compulsion urge.', 'Give a client a concrete skill to use during the delay before a compulsion.', array['Adults', 'Teens']::text[], '10 minutes', 'A delay period on its own can feel like an empty wait that makes the urge harder to resist. Pairing the delay with an active distress tolerance skill, a cold object, paced breathing, brief movement, gives the client something to do with the wait rather than just enduring it, which tends to make the delay easier to hold.', '[{"id": "f0", "type": "textarea", "label": "The urge I''m delaying"}, {"id": "f1", "type": "textarea", "label": "The skill I used during the delay"}, {"id": "f2", "type": "textarea", "label": "How intense the urge felt before and after the delay"}, {"id": "f3", "type": "textarea", "label": "How the delay went overall"}]'::jsonb, array['OCD', 'distress tolerance', 'urges']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('partner-reassurance-boundary-agreement', 'Partner Reassurance Boundary Agreement', 'couples'::resource_kind, 'A couple agrees on a shared, limited way to respond to reassurance-seeking around OCD.', 'Reduce a partner''s participation in a reassurance cycle while staying warm and supportive.', array['Couples']::text[], '20 minutes', 'A partner answering reassurance questions over and over often feels like the caring thing to do but tends to keep the cycle going, since the relief never lasts. Agreeing together on a limited, warm response, one answer and then a gentle redirect, gives the supporting partner a way to stay kind without feeding the cycle, and gives the other partner a predictable, less punishing boundary.', '[{"id": "f0", "type": "textarea", "label": "Partner with OCD: a reassurance question I ask often"}, {"id": "f1", "type": "textarea", "label": "Supporting partner: what I usually say"}, {"id": "f2", "type": "textarea", "label": "The limited response we''re agreeing to try instead"}, {"id": "f3", "type": "textarea", "label": "How the supporting partner will handle it if the question is asked again"}]'::jsonb, array['OCD', 'family accommodation', 'couples']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('certainty-roulette-game', 'Certainty Roulette Game', 'game'::resource_kind, 'A spinning wheel lands on everyday uncertain situations for players to practice sitting with, out loud.', 'Build tolerance for uncertainty through repeated, low-stakes practice in a group.', array['Groups', 'Teens']::text[], '20 minutes', 'The wheel lands on an everyday uncertain situation, did I lock the door, will they like this, and the player says out loud how they would sit with not knowing rather than checking or seeking reassurance. Hearing other players do the same normalizes the discomfort of uncertainty and builds a shared vocabulary for tolerating it.', '[{"id": "f0", "type": "textarea", "label": "The uncertain situation the wheel landed on"}, {"id": "f1", "type": "textarea", "label": "How I''d sit with not knowing, out loud"}, {"id": "f2", "type": "textarea", "label": "How uncomfortable that felt, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "A real uncertainty this reminded me of"}]'::jsonb, array['OCD', 'uncertainty', 'group']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('brain-bully-puppet-show', 'Brain Bully Puppet Show', 'kids'::resource_kind, 'A child uses a puppet to talk back to the brain bully that demands a ritual be done.', 'Give a child an externalized, playful way to resist a compulsion''s demands.', array['Children']::text[], '20 minutes', 'The child names and builds a simple puppet for the brain bully that pushes them to repeat a ritual, then practices talking back to it out loud with the parent''s support. Externalizing the urge as a character the child can argue with, rather than a part of themselves, makes it easier to resist without shame. Keep the tone playful and the parent involved as a coach, not a judge.', '[{"id": "f0", "type": "textarea", "label": "What my brain bully puppet looks like"}, {"id": "f1", "type": "textarea", "label": "What it usually tells me to do"}, {"id": "f2", "type": "textarea", "label": "What I said back to it today"}, {"id": "f3", "type": "textarea", "label": "How it felt to talk back instead of listening"}]'::jsonb, array['OCD', 'children', 'externalizing']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('panic-wave-drawing-for-teens', 'Panic Wave Drawing for Teens', 'kids'::resource_kind, 'A teen draws the rise and fall of a panic episode as a wave to build trust that it passes.', 'Help a teen see a panic episode as something that rises and falls rather than something dangerous.', array['Teens']::text[], '10 minutes after an episode', 'After a panic episode has passed, the teen draws its shape as a wave, marking the peak and how long it took to settle, with a trusted adult available to talk it through afterward rather than during. Seeing the shape on paper across a few episodes helps a teen trust the pattern: it rises, it peaks, it comes back down, every time.', '[{"id": "f0", "type": "textarea", "label": "What was happening right before the wave started"}, {"id": "f1", "type": "textarea", "label": "How intense the peak felt, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "How long it took to come back down"}, {"id": "f3", "type": "textarea", "label": "What helped, even a little, while I waited"}]'::jsonb, array['panic attacks', 'children', 'self-monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('panic-fact-or-myth-game', 'Panic Fact or Myth Game', 'game'::resource_kind, 'A group sorts common statements about panic into fact or myth and discusses what''s actually happening in the body.', 'Correct scary misunderstandings about panic through playful group discussion.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Teams sort statements, panic can make you faint, a racing heart during panic is dangerous, into fact or myth, then discuss what is actually happening in the body during a panic wave. Correcting scary misunderstandings in a low-stakes group setting tends to land better than a one-on-one lecture, since players hear the same reassurance from a teammate''s own experience too.', '[{"id": "f0", "type": "textarea", "label": "A statement I thought was fact that turned out to be a myth"}, {"id": "f1", "type": "textarea", "label": "What actually happens in the body instead"}, {"id": "f2", "type": "textarea", "label": "A statement I already knew was a myth"}, {"id": "f3", "type": "textarea", "label": "How this changes what I''ll tell myself during panic"}]'::jsonb, array['panic attacks', 'group', 'psychoeducation']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('post-panic-debrief-sheet', 'Post-Panic Debrief Sheet', 'worksheet'::resource_kind, 'A short debrief to fill out after a panic episode has fully passed, to build pattern recognition over time.', 'Build a client''s pattern recognition around what precedes and follows a panic episode.', array['Adults', 'Teens']::text[], '10 minutes, after an episode', 'Filling this out during a panic episode is not the goal; it is meant for afterward, once things have settled, so the client can build pattern recognition without adding pressure in the moment itself. Over several entries, common precedents, poor sleep, a specific place, skipped meals, tend to surface, giving the client something concrete to plan around.', '[{"id": "f0", "type": "textarea", "label": "What was happening in the hour before"}, {"id": "f1", "type": "textarea", "label": "How the episode started"}, {"id": "f2", "type": "textarea", "label": "How long it lasted"}, {"id": "f3", "type": "textarea", "label": "What helped it pass"}, {"id": "f4", "type": "textarea", "label": "A pattern I''m starting to notice across entries"}]'::jsonb, array['panic attacks', 'self-monitoring', 'formulation']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('willingness-to-ride-it-out-card', 'Willingness to Ride It Out Card', 'act'::resource_kind, 'A pocket card practicing willingness to let a panic wave run its course instead of fighting it.', 'Reduce the fight against panic sensations that tends to prolong them.', array['Adults', 'Teens']::text[], 'Five minutes', 'Fighting panic sensations, trying to make them stop immediately, often keeps the alarm system activated longer than letting the wave run its natural course. A short card the client can read during an episode, reminding them the sensations are uncomfortable but not dangerous and will pass on their own, practices willingness instead of struggle. Rehearse this outside of an episode first.', '[{"id": "f0", "type": "textarea", "label": "What I usually try to do to make panic stop immediately"}, {"id": "f1", "type": "textarea", "label": "What happens when I fight it that way"}, {"id": "f2", "type": "textarea", "label": "The willingness statement I want on my card"}, {"id": "f3", "type": "textarea", "label": "What it felt like to try willingness instead of fighting, even once"}]'::jsonb, array['panic attacks', 'willingness', 'core ACT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('paired-breath-and-cold-water-combo', 'Paired Breath and Cold Water Combo', 'dbt'::resource_kind, 'Pairs paced breathing with a brief cold-water skill for a fast physiological reset during panic.', 'Give a client a fast, body-based combination for interrupting a panic spike.', array['Adults', 'Teens']::text[], 'Five minutes', 'A panic spike is a body event first, which means a body-based skill often works faster than a thinking-based one in the first minute. Pairing a splash of cold water or a cold object held to the face with slow, extended exhales gives the client a fast, reliable combination to reach for, and rehearsing it calm makes it easier to access when panic actually hits.', '[{"id": "f0", "type": "textarea", "label": "How intense the panic felt before, 0 to 10"}, {"id": "f1", "type": "textarea", "label": "The cold-water option I used"}, {"id": "f2", "type": "textarea", "label": "How my breathing felt during the combo"}, {"id": "f3", "type": "textarea", "label": "How intense it felt after, 0 to 10"}]'::jsonb, array['panic attacks', 'distress tolerance', 'regulation']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('parent-assumption-check-sheet', 'Parent Assumption Check Sheet', 'cbt'::resource_kind, 'Checks a parent''s assumption about a child''s behavior against other possible explanations.', 'Help a parent widen their read of a child''s behavior before reacting to it.', array['Adults']::text[], '15 minutes', 'A parent''s first read of a child''s behavior, they are doing this on purpose, they don''t respect me, often narrows the response before other explanations get considered. Writing out the assumption next to a few other possible reasons for the same behavior, tiredness, a skill the child hasn''t learned yet, a need not being met, gives the parent more than one way to respond.', '[{"id": "f0", "type": "textarea", "label": "The behavior that triggered a reaction"}, {"id": "f1", "type": "textarea", "label": "My first assumption about why"}, {"id": "f2", "type": "textarea", "label": "Another possible reason for the same behavior"}, {"id": "f3", "type": "textarea", "label": "How my response might change with the other reason in mind"}]'::jsonb, array['parenting', 'thinking traps', 'core CBT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('family-feelings-charades-night', 'Family Feelings Charades Night', 'game'::resource_kind, 'A family game night where members act out feelings for others to guess, building shared vocabulary.', 'Build a family''s shared, comfortable vocabulary for naming feelings.', array['Adults', 'Children', 'Groups']::text[], '20 minutes', 'Each family member takes a turn acting out a feeling without words while the rest guess, then briefly shares a recent moment they felt that way. Parents modeling their own feelings in the game, including harder ones like frustration, gives children permission to do the same, and the shared laughter tends to lower the guard around a topic families often avoid.', '[{"id": "f0", "type": "textarea", "label": "The feeling I acted out"}, {"id": "f1", "type": "textarea", "label": "A recent moment I felt that way"}, {"id": "f2", "type": "textarea", "label": "A feeling someone else acted out that was hard to guess"}, {"id": "f3", "type": "textarea", "label": "What I noticed about how our family talks about feelings"}]'::jsonb, array['parenting', 'family', 'group']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('parenting-values-under-pressure-practice', 'Parenting Values Under Pressure Practice', 'act'::resource_kind, 'Helps a parent name the parent they want to be before a predictably stressful moment hits.', 'Reduce reactive parenting by naming values before, not during, a stressful moment.', array['Adults']::text[], '15 minutes', 'Most parents can describe the kind of parent they want to be, but that description tends to disappear exactly when a predictable trigger, bedtime, a meltdown in public, hits. Naming the value in advance, and one concrete way to act on it in that specific moment, gives the parent something to reach for when the pressure is on, rather than reflecting only after the fact.', '[{"id": "f0", "type": "textarea", "label": "A predictable stressful parenting moment"}, {"id": "f1", "type": "textarea", "label": "The kind of parent I want to be in that moment"}, {"id": "f2", "type": "textarea", "label": "One concrete way to act on that value when it happens"}, {"id": "f3", "type": "textarea", "label": "How today''s version compared to that value"}]'::jsonb, array['parenting', 'values', 'core ACT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('co-parenting-discipline-alignment-sheet', 'Co-Parenting Discipline Alignment Sheet', 'couples'::resource_kind, 'Helps two parents align on discipline approaches before a child learns to play them against each other.', 'Reduce parenting conflict by getting two parents'' discipline approaches on the same page.', array['Couples']::text[], '25 minutes', 'Children notice quickly when parents disagree on discipline, and inconsistency between two adults tends to create more conflict than either approach alone would. Comparing each parent''s instinct on a few common scenarios, then agreeing on one shared approach for each, gives a child consistency and takes a recurring argument off the table between the parents.', '[{"id": "f0", "type": "textarea", "label": "Parent A: how I''d usually handle this scenario"}, {"id": "f1", "type": "textarea", "label": "Parent B: how I''d usually handle this scenario"}, {"id": "f2", "type": "textarea", "label": "The scenario we''re discussing"}, {"id": "f3", "type": "textarea", "label": "The shared approach we''re agreeing on"}, {"id": "f4", "type": "textarea", "label": "How we''ll handle it if one of us slips back into old habits"}]'::jsonb, array['parenting', 'couples', 'behavioral']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('good-choices-sticker-map', 'Good Choices Sticker Map', 'kids'::resource_kind, 'A child places a sticker on a house-shaped map each time they make a choice the family values.', 'Give a child a visible, positive record of choices that reflect family values.', array['Children']::text[], 'Ongoing, five minutes daily', 'The parent and child pick a few family values together, sharing, kindness, trying again after a mistake, and the child adds a sticker to a house-shaped map whenever they notice themselves living one out. Keep the focus on noticing rather than earning a reward; the map is meant to build a felt sense of being a person who makes good choices, not a transaction.', '[{"id": "f0", "type": "textarea", "label": "The value I lived out today"}, {"id": "f1", "type": "textarea", "label": "What I did"}, {"id": "f2", "type": "textarea", "label": "Where I placed my sticker on the map"}, {"id": "f3", "type": "textarea", "label": "A value I want to practice more tomorrow"}]'::jsonb, array['parenting', 'children', 'behavioral']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('welcoming-the-baby-sibling-craft', 'Welcoming the Baby Sibling Craft', 'kids'::resource_kind, 'An older sibling makes a welcome card and keepsake box for the new baby to process the change.', 'Give an older sibling a hands-on way to process becoming a big sibling.', array['Children']::text[], '20 minutes', 'The parent and child make a welcome card together and a small keepsake box for a few things the child wants to save from this time, which gives the change a concrete, positive marker rather than leaving it to sink in unnoticed. Make room for the child to mention a harder feeling too, less attention, a new routine, and receive it as calmly as the excited parts.', '[{"id": "f0", "type": "textarea", "label": "What I wrote or drew on my welcome card"}, {"id": "f1", "type": "textarea", "label": "What I put in my keepsake box"}, {"id": "f2", "type": "textarea", "label": "Something I''m excited about"}, {"id": "f3", "type": "textarea", "label": "Something that''s felt different since the baby came"}]'::jsonb, array['perinatal and postpartum', 'children', 'family']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('new-parent-expectation-gap-log', 'New Parent Expectation Gap Log', 'cbt'::resource_kind, 'Compares a new parent''s expectations of parenthood to their actual daily experience.', 'Reduce the guilt that comes from an unexamined gap between expectation and reality.', array['Adults']::text[], '15 minutes', 'New parents often carry an unexamined picture of what parenthood was supposed to feel like, and the daily gap between that picture and reality can quietly breed guilt. Writing both side by side, without judging either one, usually reveals that the expectation was never realistic to begin with, which takes some of the self-blame out of an ordinary hard day.', '[{"id": "f0", "type": "textarea", "label": "What I expected this stage of parenthood to feel like"}, {"id": "f1", "type": "textarea", "label": "What it''s actually felt like this week"}, {"id": "f2", "type": "textarea", "label": "Where the gap feels biggest"}, {"id": "f3", "type": "textarea", "label": "Where the expectation, on reflection, was never realistic"}]'::jsonb, array['perinatal and postpartum', 'thinking traps', 'core CBT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('sleep-deprived-decision-delay-skill', 'Sleep-Deprived Decision Delay Skill', 'dbt'::resource_kind, 'A skill for postponing high-stakes decisions until after a stretch of better sleep.', 'Protect a sleep-deprived new parent from making big decisions under poor conditions.', array['Adults']::text[], '10 minutes', 'Severe sleep deprivation affects judgment the way any other vulnerability factor does, which makes it a poor condition for big decisions, quitting something, a major purchase, a relationship ultimatum. Building a simple rule, delay any decision above a certain size until after a real stretch of sleep, protects the new parent from choices made under conditions they wouldn''t trust for anyone else.', '[{"id": "f0", "type": "textarea", "label": "A decision I''m considering right now"}, {"id": "f1", "type": "textarea", "label": "How many hours of real sleep I''ve had recently"}, {"id": "f2", "type": "textarea", "label": "Whether this decision can wait"}, {"id": "f3", "type": "textarea", "label": "When I''ll revisit it"}]'::jsonb, array['perinatal and postpartum', 'vulnerability factors', 'regulation']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('new-parent-bingo', 'New Parent Bingo', 'game'::resource_kind, 'A bingo card of common new-parent moments, normalizing the chaos through shared recognition.', 'Normalize the messiness of early parenthood through shared, playful recognition.', array['Groups', 'Adults']::text[], '20 minutes', 'Each square names a common new-parent moment, wearing yesterday''s shirt, forgetting a name mid-sentence, and players mark a square when it has happened to them, calling bingo when a row fills in. The playful format takes some of the shame out of moments that can otherwise feel like private failures, since the room usually fills in the same squares together.', '[{"id": "f0", "type": "textarea", "label": "A square I marked and the story behind it"}, {"id": "f1", "type": "textarea", "label": "A square that hasn''t happened to me yet"}, {"id": "f2", "type": "textarea", "label": "How it felt to hear other parents share the same squares"}, {"id": "f3", "type": "textarea", "label": "One moment this reminded me to be gentler with myself about"}]'::jsonb, array['perinatal and postpartum', 'group', 'play']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('who-i-still-am-practice', 'Who I Still Am Practice', 'act'::resource_kind, 'Names parts of a client''s identity that existed before parenthood and still matter now.', 'Help a new parent hold onto a fuller sense of self alongside the parenting role.', array['Adults']::text[], '15 minutes', 'Parenthood can crowd out every other part of a client''s identity, at least for a while, which makes it easy to lose track of who they were before. Naming a few values or interests that predate the baby, and one small, realistic way to touch one of them this week, does not compete with parenting; it protects a fuller sense of self alongside it.', '[{"id": "f0", "type": "textarea", "label": "A part of who I am that existed before the baby"}, {"id": "f1", "type": "textarea", "label": "How much room it''s had lately"}, {"id": "f2", "type": "textarea", "label": "One small way to touch it this week"}, {"id": "f3", "type": "textarea", "label": "What holding onto this part of myself might give the baby too"}]'::jsonb, array['perinatal and postpartum', 'identity', 'core ACT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('unconditional-worth-reminder-sheet', 'Unconditional Worth Reminder Sheet', 'worksheet'::resource_kind, 'Separates a client''s sense of worth from their most recent performance or mistake.', 'Help a client locate a sense of worth that doesn''t rise and fall with performance.', array['Adults', 'Teens']::text[], '15 minutes', 'A client whose self-worth tracks their last success or failure is on an exhausting treadmill that never settles. Listing qualities and relationships that stay true regardless of a recent mistake or win, being someone people trust, being curious, being kind, gives the client a more stable place to stand than the next performance.', '[{"id": "f0", "type": "textarea", "label": "A recent success or failure that''s been shaping how I feel about myself"}, {"id": "f1", "type": "textarea", "label": "Something true about me that doesn''t depend on that outcome"}, {"id": "f2", "type": "textarea", "label": "Another steady quality or relationship I can name"}, {"id": "f3", "type": "textarea", "label": "How thinking about these changes today''s feeling"}]'::jsonb, array['self-esteem', 'core beliefs', 'self-compassion']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('superlatives-circle-game', 'Superlatives Circle Game', 'game'::resource_kind, 'A group takes turns naming a genuine positive superlative for each member.', 'Build a group''s practice of giving and receiving specific, genuine praise.', array['Groups', 'Teens']::text[], '20 minutes', 'Going around the circle, each member receives one specific, genuine superlative from every other player, best listener, most likely to notice when someone''s off, and simply says thank you rather than deflecting it. Practicing receiving praise without minimizing it is often harder than giving it, and the debrief usually surfaces which one felt harder for each player.', '[{"id": "f0", "type": "textarea", "label": "A superlative I received that surprised me"}, {"id": "f1", "type": "textarea", "label": "A superlative I gave that I meant sincerely"}, {"id": "f2", "type": "textarea", "label": "Whether it was harder to give or receive praise, and why"}, {"id": "f3", "type": "textarea", "label": "One thing I want to remember from what I heard"}]'::jsonb, array['self-esteem', 'group', 'play']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('double-standard-question', 'Double Standard Question', 'cbt'::resource_kind, 'Tests a client''s harsh self-judgment by asking whether they''d say the same to a friend.', 'Surface the double standard between how a client judges themselves and others.', array['Adults', 'Teens']::text[], '10 minutes', 'Clients with low self-esteem often hold themselves to a standard they would never apply to someone they care about. Writing the harsh self-judgment down, then asking what they would actually say to a friend in the same situation, and why the difference exists, is a quick, repeatable way to catch the double standard in the moment it is happening.', '[{"id": "f0", "type": "textarea", "label": "The harsh thing I said to myself"}, {"id": "f1", "type": "textarea", "label": "What I''d say to a friend in the same situation"}, {"id": "f2", "type": "textarea", "label": "Why the standard is different"}, {"id": "f3", "type": "textarea", "label": "A more even-handed version of my original thought"}]'::jsonb, array['self-esteem', 'thinking traps', 'core CBT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('reflected-strengths-letter-exchange', 'Reflected Strengths Letter Exchange', 'couples'::resource_kind, 'Partners write each other a letter naming strengths the other may not see in themselves.', 'Help a partner with low self-esteem hear their strengths reflected by someone who knows them well.', array['Couples']::text[], '20 minutes', 'A partner struggling with self-esteem often cannot see strengths that are obvious to the person who knows them best. Each partner writes a short letter naming a few specific strengths they see in the other, with concrete examples rather than general compliments, and reads it aloud rather than just handing it over. Keep the focus on receiving rather than deflecting.', '[{"id": "f0", "type": "textarea", "label": "Partner A: strengths I see in my partner, with examples"}, {"id": "f1", "type": "textarea", "label": "Partner B: strengths I see in my partner, with examples"}, {"id": "f2", "type": "textarea", "label": "A strength named that I hadn''t recognized in myself"}, {"id": "f3", "type": "textarea", "label": "What it felt like to hear it read aloud"}]'::jsonb, array['self-esteem', 'couples', 'strengths']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('strengths-superhero-cape-craft', 'Strengths Superhero Cape Craft', 'kids'::resource_kind, 'A child decorates a cape with symbols representing their own strengths.', 'Give a child a wearable, visible reminder of their own strengths.', array['Children']::text[], '30 minutes', 'The parent and child name a few of the child''s strengths together, kind, brave, funny, good at building things, and the child draws or paints a symbol for each on a simple fabric or paper cape. Wearing the finished cape gives the child a playful, physical reminder they can return to, and the parent can reference a symbol on a hard day rather than a lecture.', '[{"id": "f0", "type": "textarea", "label": "The strengths I chose for my cape"}, {"id": "f1", "type": "textarea", "label": "The symbol I drew for each one"}, {"id": "f2", "type": "textarea", "label": "A time one of these strengths showed up this week"}, {"id": "f3", "type": "textarea", "label": "How I feel when I wear my cape"}]'::jsonb, array['self-esteem', 'children', 'strengths']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('social-event-support-plan', 'Social Event Support Plan', 'couples'::resource_kind, 'A couple plans in advance how a supporting partner can help without taking over in a social setting.', 'Give a couple a shared plan for social events that supports rather than rescues.', array['Couples']::text[], '20 minutes', 'A supporting partner who jumps in to rescue every awkward moment can unintentionally prevent the anxious partner from building their own tolerance for social discomfort. Agreeing in advance on what kind of support actually helps, a check-in signal, staying nearby without hovering, gives both partners a plan that respects growth as well as comfort.', '[{"id": "f0", "type": "textarea", "label": "Anxious partner: what support actually helps at a social event"}, {"id": "f1", "type": "textarea", "label": "Anxious partner: what feels like being rescued instead"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: the signal I''ll watch for"}, {"id": "f3", "type": "textarea", "label": "What we''ll agree counts as a successful event, even an uncomfortable one"}]'::jsonb, array['social anxiety', 'support', 'couples']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('brave-hello-practice-chart-for-teens', 'Brave Hello Practice Chart for Teens', 'kids'::resource_kind, 'A teen tracks small, graded social approach steps like a brief hello or eye contact.', 'Build a teen''s confidence with social approach through small, graded practice.', array['Teens']::text[], '10 minutes daily', 'Social anxiety often makes even a brief hello feel disproportionately hard, so starting with the smallest possible step, eye contact, a nod, a one-word greeting, builds momentum better than aiming for a full conversation right away. The teen tracks each attempt on the chart regardless of how it went, since the practice of trying is the point, not a perfect outcome.', '[{"id": "f0", "type": "textarea", "label": "The small social step I attempted today"}, {"id": "f1", "type": "textarea", "label": "How anxious I felt before, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "How it actually went"}, {"id": "f3", "type": "textarea", "label": "The next step I want to try"}]'::jsonb, array['social anxiety', 'exposure', 'teens']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('small-talk-bingo', 'Small Talk Bingo', 'game'::resource_kind, 'A bingo card of small talk topics players practice bringing up in a low-stakes group setting.', 'Build fluency and comfort with everyday small talk through low-stakes practice.', array['Groups', 'Teens']::text[], '20 minutes', 'Each square names a small talk topic, the weather, a weekend plan, a recent show, and players mark a square when they have successfully brought it up with someone in the room. Practicing small talk as a game rather than a test lowers the stakes enough for socially anxious players to actually try, and hearing others stumble too normalizes the awkwardness.', '[{"id": "f0", "type": "textarea", "label": "A square I completed and how the conversation went"}, {"id": "f1", "type": "textarea", "label": "A square that felt hardest to bring up"}, {"id": "f2", "type": "textarea", "label": "How anxious I felt starting compared to after"}, {"id": "f3", "type": "textarea", "label": "A small talk topic I want to try outside this game"}]'::jsonb, array['social anxiety', 'group', 'play']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('post-social-replay-interrupter', 'Post-Social Replay Interrupter', 'worksheet'::resource_kind, 'Interrupts the habit of replaying a social interaction for flaws after it''s already over.', 'Help a client stop a post-event replay before it spirals into self-criticism.', array['Adults', 'Teens']::text[], '15 minutes', 'The replay that follows a social interaction, searching for every awkward moment, tends to manufacture more flaws than actually occurred. Writing down what the replay is focused on, then what a neutral bystander would likely have noticed instead, usually shows a big gap between the two, which the client can return to the next time a replay starts.', '[{"id": "f0", "type": "textarea", "label": "The interaction I''ve been replaying"}, {"id": "f1", "type": "textarea", "label": "What my replay keeps focusing on"}, {"id": "f2", "type": "textarea", "label": "What a neutral bystander probably noticed instead"}, {"id": "f3", "type": "textarea", "label": "How the gap between those two views feels"}]'::jsonb, array['social anxiety', 'rumination', 'self-monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('awkwardness-willingness-ladder', 'Awkwardness Willingness Ladder', 'act'::resource_kind, 'Builds willingness to tolerate awkward feelings through graded social steps rather than avoiding them.', 'Help a client build tolerance for awkwardness instead of avoiding situations that might cause it.', array['Adults', 'Teens']::text[], '20 minutes', 'Avoiding every situation that might feel awkward keeps a client''s world small and the fear of awkwardness untested. Ranking a short list of social steps by how much awkwardness each might bring, then choosing willingness to feel that discomfort rather than certainty it won''t happen, lets the client move up the ladder at a pace that still feels workable.', '[{"id": "f0", "type": "textarea", "label": "A social step low on my awkwardness ladder"}, {"id": "f1", "type": "textarea", "label": "A step higher up"}, {"id": "f2", "type": "textarea", "label": "The step I''m willing to try this week"}, {"id": "f3", "type": "textarea", "label": "What I''m willing to feel in order to try it"}]'::jsonb, array['social anxiety', 'willingness', 'core ACT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('grief-and-values-coexistence-practice', 'Grief and Values Coexistence Practice', 'act'::resource_kind, 'Practices holding grief and continued engagement with values side by side rather than as opposites.', 'Help a client see that living out their values doesn''t require grief to be finished first.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients sometimes believe they need to finish grieving before they are allowed to reengage with what matters to them, which can leave both grief and life on hold. Naming a value the client still wants to act on, and practicing carrying both the grief and the value in the same moment rather than waiting for one to end, opens room to live alongside loss rather than after it.', '[{"id": "f0", "type": "textarea", "label": "A value I want to keep acting on"}, {"id": "f1", "type": "textarea", "label": "What''s made that feel impossible while grieving"}, {"id": "f2", "type": "textarea", "label": "What it might look like to carry both grief and this value at once"}, {"id": "f3", "type": "textarea", "label": "A small step toward the value I could take this week"}]'::jsonb, array['grief and loss', 'values', 'core ACT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('anniversary-and-milestone-planning-sheet', 'Anniversary and Milestone Planning Sheet', 'worksheet'::resource_kind, 'Plans in advance for an upcoming anniversary, holiday or milestone likely to bring grief to the surface.', 'Reduce the shock of a grief spike by planning for a known difficult date in advance.', array['Adults', 'Teens']::text[], '20 minutes', 'A known difficult date, an anniversary, a birthday, a first holiday without someone, tends to bring grief closer to the surface, and planning for it in advance softens the impact more than hoping it won''t be that hard. Naming what kind of day the client wants, alone or with others, marking it or trying to move past it, and one support person to have on call, turns a dreaded date into something with a plan.', '[{"id": "f0", "type": "textarea", "label": "The upcoming date and what it marks"}, {"id": "f1", "type": "textarea", "label": "What kind of day I want this to be"}, {"id": "f2", "type": "textarea", "label": "One way I want to mark or acknowledge it"}, {"id": "f3", "type": "textarea", "label": "A support person I''ll have on call that day"}, {"id": "f4", "type": "textarea", "label": "What I''ll do if it''s harder than expected"}]'::jsonb, array['grief and loss', 'planning', 'self-monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('grief-timeline-differences-conversation', 'Grief Timeline Differences Conversation', 'couples'::resource_kind, 'Helps a couple understand why they''re grieving a shared loss on different timelines.', 'Reduce conflict between partners grieving the same loss at different paces.', array['Couples']::text[], '25 minutes', 'Two partners grieving the same loss rarely move at the same pace, and the difference can be mistaken for one partner caring less or the other being stuck. Each partner describes where they are right now, without comparing it to the other''s pace, which usually reveals that both are grieving fully, just differently, and opens room for patience instead of pressure.', '[{"id": "f0", "type": "textarea", "label": "Partner A: where I am with this grief right now"}, {"id": "f1", "type": "textarea", "label": "Partner B: where I am with this grief right now"}, {"id": "f2", "type": "textarea", "label": "A moment the difference in our pace caused friction"}, {"id": "f3", "type": "textarea", "label": "What patience with each other''s pace could look like"}]'::jsonb, array['grief and loss', 'couples', 'communication']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('guilt-thought-audit', 'Guilt Thought Audit', 'cbt'::resource_kind, 'Audits guilt-laden thoughts about what a client could have done differently before a loss.', 'Separate a grieving client''s guilt from what they actually had control over.', array['Adults', 'Teens']::text[], '15 minutes', 'Grief often comes packaged with guilt, a should-have or if-only, that feels like fact but rarely holds up against what the client actually knew and controlled at the time. Writing the guilty thought down, then what information and choices were actually available in that moment, separates hindsight from what was realistically possible, which does not erase the grief but can loosen the guilt.', '[{"id": "f0", "type": "textarea", "label": "The guilty thought I keep returning to"}, {"id": "f1", "type": "textarea", "label": "What I actually knew at the time"}, {"id": "f2", "type": "textarea", "label": "What was and wasn''t within my control"}, {"id": "f3", "type": "textarea", "label": "How the thought looks with that context added"}]'::jsonb, array['grief and loss', 'guilt', 'core CBT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('remembering-together-memory-jar', 'Remembering Together Memory Jar', 'kids'::resource_kind, 'A family adds memories of someone who died to a jar, to keep and revisit together.', 'Give a child a concrete, ongoing way to keep memories alive rather than avoiding the topic.', array['Children']::text[], '10 minutes, ongoing', 'The family keeps a jar where anyone can add a written or drawn memory of the person who died, whenever one comes to mind, and revisits it together occasionally rather than only around hard dates. This gives a child permission to bring up memories outside of the moments adults expect grief to show up, and shows that remembering can include warmth, not only sadness.', '[{"id": "f0", "type": "textarea", "label": "A memory I added to the jar"}, {"id": "f1", "type": "textarea", "label": "Why I thought of it today"}, {"id": "f2", "type": "textarea", "label": "A memory from the jar that made me smile"}, {"id": "f3", "type": "textarea", "label": "Something I still want to remember and haven''t written down yet"}]'::jsonb, array['grief and loss', 'children', 'memory']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('relationship-needs-priority-sheet', 'Relationship Needs Priority Sheet', 'worksheet'::resource_kind, 'Ranks a client''s relationship needs to clarify what matters most before a hard conversation.', 'Help a client clarify their own priorities before bringing them into a relationship conversation.', array['Adults', 'Teens']::text[], '15 minutes', 'A client entering a relationship conversation without a clear sense of their own priorities can end up negotiating against themselves. Ranking a list of needs, more time together, more independence, more appreciation, before the conversation happens gives the client clarity about what actually matters most, rather than discovering it mid-discussion.', '[{"id": "f0", "type": "textarea", "label": "A need I have in this relationship"}, {"id": "f1", "type": "textarea", "label": "Another need, ranked below the first"}, {"id": "f2", "type": "textarea", "label": "Which need matters most right now and why"}, {"id": "f3", "type": "textarea", "label": "How I''ll bring this priority into the conversation"}]'::jsonb, array['relationship issues', 'values', 'self-monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('partner-intent-assumption-check', 'Partner Intent Assumption Check', 'cbt'::resource_kind, 'Checks an assumed negative intent behind a partner''s behavior against other possible explanations.', 'Reduce conflict caused by assuming the worst about a partner''s intentions.', array['Adults', 'Teens']::text[], '15 minutes', 'Assuming a partner''s behavior comes from a negative intent, they don''t care, they did that on purpose, tends to escalate a small moment into a bigger conflict than the behavior alone would cause. Writing the assumption down next to a few other possible explanations, tiredness, distraction, a different priority, softens the automatic read enough to ask rather than accuse.', '[{"id": "f0", "type": "textarea", "label": "The behavior that bothered me"}, {"id": "f1", "type": "textarea", "label": "The intent I assumed behind it"}, {"id": "f2", "type": "textarea", "label": "Another possible explanation for the same behavior"}, {"id": "f3", "type": "textarea", "label": "A question I could ask instead of assuming"}]'::jsonb, array['relationship issues', 'thinking traps', 'core CBT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('relationship-repair-skills-menu', 'Relationship Repair Skills Menu', 'dbt'::resource_kind, 'A personalized menu of repair skills a client can use after a relationship conflict.', 'Give a client a ready reference for repairing connection after conflict.', array['Adults', 'Teens']::text[], '15 minutes to build, then ongoing', 'After a conflict, a client under stress often cannot think of what actually helps repair connection, even when they know from experience what has worked before. Building a short, personalized menu of repair moves, a specific apology, a small gesture, naming what happened without blame, means the client has it ready rather than improvising while still upset.', '[{"id": "f0", "type": "textarea", "label": "A repair move that''s worked for me before"}, {"id": "f1", "type": "textarea", "label": "A repair move I want to try"}, {"id": "f2", "type": "textarea", "label": "Where I''ll keep this menu accessible"}, {"id": "f3", "type": "textarea", "label": "A recent conflict this menu would have helped with"}]'::jsonb, array['relationship issues', 'repair', 'skills']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('friendship-repair-comic-strip', 'Friendship Repair Comic Strip', 'kids'::resource_kind, 'A child draws a comic strip showing a friendship conflict and how it could be repaired.', 'Give a child a concrete way to think through repairing a friendship conflict.', array['Children']::text[], '20 minutes', 'The child draws a short comic strip showing what happened in a friendship conflict, then a second strip showing how it could be repaired, an apology, an invitation to talk, a shared activity. Drawing it out rather than just discussing it gives the child room to think through the steps at their own pace, and the parent can gently ask about the ending panel if the child leaves it open.', '[{"id": "f0", "type": "textarea", "label": "What happened, drawn in my first strip"}, {"id": "f1", "type": "textarea", "label": "How I felt during the conflict"}, {"id": "f2", "type": "textarea", "label": "How the friendship could be repaired, drawn in my second strip"}, {"id": "f3", "type": "textarea", "label": "What I want to try first"}]'::jsonb, array['relationship issues', 'children', 'communication']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('relationship-bingo-everyday-repair-edition', 'Relationship Bingo: Everyday Repair Edition', 'game'::resource_kind, 'A bingo card of small, everyday relationship repair actions to notice and try.', 'Build a group''s or couple''s habit of small, everyday relationship repair.', array['Groups', 'Couples']::text[], 'One week', 'Each square names a small repair or connection action, a genuine compliment, an apology for something small, asking how someone''s day went, and players mark a square whenever they do or receive one over the course of a week. The playful format lowers the pressure of a big grand gesture and builds the habit of small, frequent repair instead.', '[{"id": "f0", "type": "textarea", "label": "A square I completed this week"}, {"id": "f1", "type": "textarea", "label": "How it landed, giving or receiving it"}, {"id": "f2", "type": "textarea", "label": "A square I want to try next"}, {"id": "f3", "type": "textarea", "label": "What this game showed me about small repairs"}]'::jsonb, array['relationship issues', 'group', 'play']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('coping-skills-draw-and-practice-game', 'Coping Skills Draw and Practice Game', 'game'::resource_kind, 'A group draws cards naming a coping skill and practices it together for a minute.', 'Build familiarity with a range of coping skills through repeated, low-stakes group practice.', array['Groups', 'Adults', 'Teens']::text[], '20 minutes', 'Each card names a coping skill, deep breathing, grounding, a calming phrase, and the group practices it together for a minute before rating how it felt. This is a general skills-practice game and stays there; it is not a place to discuss what happened to anyone, and facilitators should keep the focus on the skill itself.', '[{"id": "f0", "type": "textarea", "label": "A skill card I drew and how it felt to practice"}, {"id": "f1", "type": "textarea", "label": "How settled I felt after, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "A skill I want to use more"}, {"id": "f3", "type": "textarea", "label": "Where I''ll remember to use it"}]'::jsonb, array['sexual abuse', 'coping skills', 'group']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('reclaiming-small-choices-practice', 'Reclaiming Small Choices Practice', 'act'::resource_kind, 'Practices noticing and making small everyday choices to rebuild a client''s sense of agency.', 'Rebuild a client''s felt sense of choice and agency through small, present-day decisions.', array['Adults', 'Teens']::text[], '15 minutes', 'Rebuilding a sense of agency often starts small: noticing and deliberately making choices, what to eat, what to wear, how to spend a free hour, that are entirely the client''s own. This is not about the size of the choice but the felt sense of choosing it; tracking a few across a week can build evidence of agency that words alone do not provide.', '[{"id": "f0", "type": "textarea", "label": "A small choice I made today, entirely my own"}, {"id": "f1", "type": "textarea", "label": "How it felt to make that choice on purpose"}, {"id": "f2", "type": "textarea", "label": "Another small choice I want to make this week"}, {"id": "f3", "type": "textarea", "label": "What noticing these choices is building for me"}]'::jsonb, array['sexual abuse', 'agency', 'core ACT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('grounding-through-the-senses-card', 'Grounding Through the Senses Card', 'dbt'::resource_kind, 'A five-senses grounding card for moments when a client feels unsafe in the present moment.', 'Give a client a fast, reliable way to return to present-moment safety.', array['Adults', 'Teens']::text[], 'Five minutes', 'When a feeling of unsafety surfaces without a present-day cause, orienting deliberately to the five senses can help the body catch up to the fact that the current moment is safe. This card is for use in the moment, naming what''s seen, heard, felt, smelled and, if appropriate, tasted, and is meant to support safety and grounding, not to explore what happened.', '[{"id": "f0", "type": "textarea", "label": "What I can see right now"}, {"id": "f1", "type": "textarea", "label": "What I can hear right now"}, {"id": "f2", "type": "textarea", "label": "What I can feel touching my skin right now"}, {"id": "f3", "type": "textarea", "label": "What I can smell right now"}, {"id": "f4", "type": "textarea", "label": "How settled I feel now, compared to before"}]'::jsonb, array['sexual abuse', 'grounding', 'distress tolerance']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('my-body-my-say-poster', 'My Body, My Say Poster', 'kids'::resource_kind, 'A child decorates a poster naming the trusted adults they can tell if something feels wrong.', 'Reinforce a child''s sense that their body belongs to them and who they can tell if that isn''t respected.', array['Children']::text[], '20 minutes', 'The parent and child name a short list of trusted adults, drawn or written on a poster, the child can go to if anything ever feels wrong or confusing about their body or safety. Keep the language simple and reassuring rather than frightening, and let the child ask questions at their own pace. As with any tool for children, a disclosure during this activity carries the clinician''s usual reporting duties.', '[{"id": "f0", "type": "textarea", "label": "The trusted adults I named"}, {"id": "f1", "type": "textarea", "label": "What I can say if something feels wrong"}, {"id": "f2", "type": "textarea", "label": "Where I''ll keep this poster"}, {"id": "f3", "type": "textarea", "label": "A question I still have"}]'::jsonb, array['sexual abuse', 'children', 'safety']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('supporting-a-partners-pace-agreement', 'Supporting a Partner''s Pace Agreement', 'couples'::resource_kind, 'Helps a couple agree on physical and emotional intimacy moving at the survivor partner''s pace.', 'Give a couple a shared, explicit agreement about pacing intimacy around a survivor partner''s needs.', array['Couples']::text[], '20 minutes', 'A supporting partner''s good intentions can still move faster than a survivor partner''s actual readiness, especially around physical closeness. Naming a clear, revisitable agreement, what pace feels right, what check-in language either partner can use, how the survivor partner can pause without it being taken personally, gives both partners something explicit to work from rather than guessing.', '[{"id": "f0", "type": "textarea", "label": "Survivor partner: what pace feels right for me right now"}, {"id": "f1", "type": "textarea", "label": "Supporting partner: what I want to understand about that pace"}, {"id": "f2", "type": "textarea", "label": "The check-in language we''re agreeing on"}, {"id": "f3", "type": "textarea", "label": "How the survivor partner can pause without it being taken personally"}]'::jsonb, array['sexual abuse', 'support', 'couples']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('couple-coping-skills-inventory', 'Couple Coping Skills Inventory', 'couples'::resource_kind, 'Each partner shares which coping skills actually work for them so the other can support, not guess.', 'Help partners support each other''s coping with informed help instead of guessing.', array['Couples']::text[], '20 minutes', 'A well-meaning partner often reaches for whatever coping method works for them, which may be exactly wrong for the other. Each partner names a short, honest inventory of what actually helps them cope, and what doesn''t, however that compares to what the other partner assumed, gives both a more accurate map to work from during a hard moment.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what actually helps me cope"}, {"id": "f1", "type": "textarea", "label": "Partner A: what doesn''t help, even if well-meant"}, {"id": "f2", "type": "textarea", "label": "Partner B: what actually helps me cope"}, {"id": "f3", "type": "textarea", "label": "Partner B: what doesn''t help, even if well-meant"}, {"id": "f4", "type": "textarea", "label": "One thing each of us learned that surprised us"}]'::jsonb, array['coping skills', 'couples', 'support']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('coping-skill-rotation-card', 'Coping Skill Rotation Card', 'dbt'::resource_kind, 'Tracks which coping skills are overused or underused to keep a client''s toolkit balanced.', 'Prevent a client from relying on the same one or two coping skills to the exclusion of others.', array['Adults', 'Teens']::text[], 'Ongoing, brief entries', 'Clients often default to the same one or two coping skills, which can work fine until that skill isn''t available or stops being enough on its own. Logging which skill was used each time, over a couple of weeks, shows the client their own pattern and makes room to deliberately practice an underused skill before it is needed under pressure.', '[{"id": "f0", "type": "textarea", "label": "The coping skill I used today"}, {"id": "f1", "type": "textarea", "label": "How well it worked, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "A skill from my list I haven''t used in a while"}, {"id": "f3", "type": "textarea", "label": "When I could try that underused skill this week"}]'::jsonb, array['coping skills', 'self-monitoring', 'skills']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('coping-skill-matching-thoughts-sheet', 'Coping Skill Matching Thoughts Sheet', 'cbt'::resource_kind, 'Matches a coping skill to the specific kind of thought or feeling driving distress in the moment.', 'Help a client choose a coping skill that fits the actual problem, not just habit.', array['Adults', 'Teens']::text[], '15 minutes', 'Not every coping skill fits every kind of distress: a grounding skill helps a racing body more than a spiraling thought, and a thought-challenging skill helps a spiraling thought more than a racing body. Naming what is actually driving the distress in the moment, body or thoughts, before picking a skill increases the odds the chosen skill actually helps.', '[{"id": "f0", "type": "textarea", "label": "What''s driving the distress right now, body or thoughts"}, {"id": "f1", "type": "textarea", "label": "A skill that matches a racing body"}, {"id": "f2", "type": "textarea", "label": "A skill that matches spiraling thoughts"}, {"id": "f3", "type": "textarea", "label": "Which skill I chose and how well it fit"}]'::jsonb, array['coping skills', 'self-monitoring', 'core CBT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('coping-skills-cost-of-avoidance-sheet', 'Coping Skills Cost of Avoidance Sheet', 'worksheet'::resource_kind, 'Compares the short-term relief of an avoidant coping habit to its longer-term cost.', 'Help a client see the trade-off in a coping habit that offers relief now but costs more later.', array['Adults', 'Teens']::text[], '15 minutes', 'A coping habit that offers real relief in the moment, scrolling, sleeping through a problem, avoiding a hard task, can still cost more over time than it gives back. Writing the short-term benefit next to the longer-term cost, honestly and without judgment, does not demand the client give up the habit immediately, just see the full trade they are actually making.', '[{"id": "f0", "type": "textarea", "label": "The coping habit I''m looking at"}, {"id": "f1", "type": "textarea", "label": "What it gives me in the short term"}, {"id": "f2", "type": "textarea", "label": "What it costs me over the longer term"}, {"id": "f3", "type": "textarea", "label": "A coping skill that might give some of the same relief at less cost"}]'::jsonb, array['coping skills', 'self-monitoring', 'planning']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('calm-down-recipe-card-craft', 'Calm Down Recipe Card Craft', 'kids'::resource_kind, 'A child writes their own recipe of steps that helps them calm down, like a recipe card.', 'Give a child a concrete, personalized sequence of coping steps they helped create.', array['Children']::text[], '20 minutes', 'The parent and child decorate a recipe card together, but instead of food, it lists the child''s own steps for calming down, a few deep breaths, a favorite stuffed animal, a quiet corner, in the order that works for them. Having the child choose and order the steps themselves builds ownership, and the finished card becomes something the parent can point to instead of instructing in the moment.', '[{"id": "f0", "type": "textarea", "label": "The steps in my calm-down recipe, in order"}, {"id": "f1", "type": "textarea", "label": "Which step usually helps most"}, {"id": "f2", "type": "textarea", "label": "Where I''ll keep my recipe card"}, {"id": "f3", "type": "textarea", "label": "A time I used my recipe this week"}]'::jsonb, array['coping skills', 'children', 'self-monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('willingness-over-certainty-ladder', 'Willingness Over Certainty Ladder', 'act'::resource_kind, 'Reframes exposure steps around a client''s willingness to feel fear rather than certainty they won''t.', 'Shift a client''s exposure practice from seeking certainty to practicing willingness.', array['Adults', 'Teens']::text[], '20 minutes', 'Waiting to feel certain the feared thing won''t happen before taking a step keeps a client stuck, since the certainty they are waiting for rarely arrives. Reframing each step on the ladder around willingness to feel the fear, rather than a guarantee of safety, lets the client move even while afraid, which is what actually builds the new pattern.', '[{"id": "f0", "type": "textarea", "label": "The feared situation"}, {"id": "f1", "type": "textarea", "label": "A step on the ladder I could take this week"}, {"id": "f2", "type": "textarea", "label": "What certainty I''ve been waiting for that isn''t coming"}, {"id": "f3", "type": "textarea", "label": "What I''m willing to feel in order to take the step anyway"}]'::jsonb, array['phobias', 'willingness', 'core ACT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('fear-ladder-trivia-challenge', 'Fear Ladder Trivia Challenge', 'game'::resource_kind, 'A trivia game testing knowledge of common fear responses and matching approach strategies.', 'Build shared, playful knowledge of how exposure and fear responses actually work.', array['Groups', 'Teens']::text[], '20 minutes', 'Teams answer trivia questions about how fear responses work, why avoidance keeps fear alive, what happens to fear with repeated approach, scoring bonus points for sharing a personal example. Making the mechanics of fear into a shared, playful challenge tends to demystify it more effectively than a straightforward explanation alone.', '[{"id": "f0", "type": "textarea", "label": "A trivia question I answered"}, {"id": "f1", "type": "textarea", "label": "What I learned about how fear actually works"}, {"id": "f2", "type": "textarea", "label": "A personal example I shared"}, {"id": "f3", "type": "textarea", "label": "How this changes how I think about my own fear"}]'::jsonb, array['phobias', 'group', 'psychoeducation']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('exposure-support-without-rescuing-sheet', 'Exposure Support Without Rescuing Sheet', 'couples'::resource_kind, 'Helps a couple agree on support during exposure practice that doesn''t accidentally rescue from the fear.', 'Give a couple a shared plan for exposure support that builds rather than undermines progress.', array['Couples']::text[], '20 minutes', 'A supporting partner who steps in the moment fear rises, taking over, offering an escape, can unintentionally undo the value of an exposure step. Agreeing in advance on what support looks like, staying present without taking over, a specific phrase of encouragement, gives both partners a plan that respects the process instead of shortcutting it out of care.', '[{"id": "f0", "type": "textarea", "label": "Partner practicing exposure: what support actually helps"}, {"id": "f1", "type": "textarea", "label": "Partner practicing exposure: what feels like rescuing instead"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: the phrase or action I''ll use to encourage, not rescue"}, {"id": "f3", "type": "textarea", "label": "How we''ll know a step counted as a success, even if it was hard"}]'::jsonb, array['phobias', 'support', 'couples']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('feared-outcome-prediction-sheet', 'Feared Outcome Prediction Sheet', 'cbt'::resource_kind, 'Records a client''s predicted worst outcome before an exposure step, then compares it to what happens.', 'Build evidence against a phobia''s predicted catastrophe through repeated real-world comparison.', array['Adults', 'Teens']::text[], '15 minutes', 'A phobia usually comes with a specific predicted catastrophe attached to the feared object or situation. Writing the exact prediction down before an exposure step, then what actually happened afterward, builds a growing, personal record that the predicted outcome doesn''t match reality, which does more than reassurance alone.', '[{"id": "f0", "type": "textarea", "label": "The exposure step I''m about to take"}, {"id": "f1", "type": "textarea", "label": "My predicted worst outcome"}, {"id": "f2", "type": "textarea", "label": "How confident I am that will happen, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "How this compares to my prediction"}]'::jsonb, array['phobias', 'behavioral experiment', 'core CBT']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('avoidance-pattern-spotter', 'Avoidance Pattern Spotter', 'worksheet'::resource_kind, 'Tracks the small, everyday ways a client avoids a feared situation beyond the obvious ones.', 'Help a client notice subtle avoidance that keeps a phobia maintained without them realizing it.', array['Adults', 'Teens']::text[], '15 minutes', 'Avoidance isn''t always as obvious as skipping the feared situation entirely; it often shows up in smaller ways, sitting near an exit, bringing a companion every time, checking obsessively before going. Logging these smaller patterns over a week usually reveals more avoidance than the client realized, which is useful information for planning the next exposure step.', '[{"id": "f0", "type": "textarea", "label": "A small avoidance I noticed this week"}, {"id": "f1", "type": "textarea", "label": "What it let me skip or soften"}, {"id": "f2", "type": "textarea", "label": "How obvious or subtle it was"}, {"id": "f3", "type": "textarea", "label": "A step I could take to reduce this specific avoidance"}]'::jsonb, array['phobias', 'avoidance', 'self-monitoring']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('body-gratitude-circle-game', 'Body Gratitude Circle Game', 'game'::resource_kind, 'A group takes turns naming something their body lets them do, building a function-focused conversation.', 'Build a group''s shared, function-focused way of talking about the body.', array['Groups', 'Teens']::text[], '20 minutes', 'Going around the circle, each player names one thing their body lets them do, run, hug someone, taste their favorite food, rather than how it looks. Keeping the conversation strictly function-focused models a different way of relating to the body than the appearance-focused talk most players are used to, and hearing a range of answers widens what counts as worth appreciating.', '[{"id": "f0", "type": "textarea", "label": "What I named my body lets me do"}, {"id": "f1", "type": "textarea", "label": "Something someone else named that I hadn''t thought of"}, {"id": "f2", "type": "textarea", "label": "How this conversation felt compared to how body talk usually goes"}, {"id": "f3", "type": "textarea", "label": "One function of my body I want to appreciate more"}]'::jsonb, array['body image', 'group', 'play']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('appearance-comment-urge-surfing-card', 'Appearance Comment Urge Surfing Card', 'dbt'::resource_kind, 'Applies urge surfing to the urge to comment critically on one''s own appearance out loud.', 'Help a client ride out the urge to voice a critical appearance comment instead of acting on it.', array['Adults', 'Teens']::text[], 'Five minutes', 'The urge to say a critical comment about appearance out loud, in a mirror, getting dressed, in a photo, often passes on its own if given a moment, the same way any other urge does. Noticing the urge rise, riding it out without saying the comment or its opposite, and noticing it fall builds practice separating the urge from the action.', '[{"id": "f0", "type": "textarea", "label": "The urge I noticed"}, {"id": "f1", "type": "textarea", "label": "How strong it felt, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What I did instead of voicing it"}, {"id": "f3", "type": "textarea", "label": "How the urge changed after I waited"}]'::jsonb, array['body image', 'urges', 'distress tolerance']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('appearance-free-compliment-practice', 'Appearance-Free Compliment Practice', 'couples'::resource_kind, 'A couple practices giving each other compliments that have nothing to do with appearance.', 'Build a couple''s habit of affirming each other in ways not tied to how they look.', array['Couples']::text[], '15 minutes', 'Compliments that default to appearance, even kind ones, can reinforce the idea that looks are the primary thing worth noticing about a partner. Practicing a round of compliments that are entirely about something else, a quality, an effort, a moment of kindness, builds a habit of affirming a partner as a whole person rather than primarily how they look.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a non-appearance compliment for my partner"}, {"id": "f1", "type": "textarea", "label": "Partner B: a non-appearance compliment for my partner"}, {"id": "f2", "type": "textarea", "label": "How it felt to give a compliment with no appearance content"}, {"id": "f3", "type": "textarea", "label": "How it felt to receive one"}]'::jsonb, array['body image', 'couples', 'communication']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('my-body-can-do-anything-drawing', 'My Body Can Do Anything Drawing', 'kids'::resource_kind, 'A child draws themselves doing something they''re proud their body can do.', 'Build a child''s early function-focused relationship with their body.', array['Children']::text[], '20 minutes', 'The child draws a picture of themselves doing something they are proud their body lets them do, climbing, dancing, riding a bike, and the parent asks about what the body was doing rather than how it looked in the picture. Keeping the conversation on ability and effort plants an early frame that resists the appearance-focused messages a child will encounter later.', '[{"id": "f0", "type": "textarea", "label": "What I drew myself doing"}, {"id": "f1", "type": "textarea", "label": "How my body helped me do it"}, {"id": "f2", "type": "textarea", "label": "How I felt while I was doing it"}, {"id": "f3", "type": "textarea", "label": "Something else my body is good at"}]'::jsonb, array['body image', 'children', 'art']::text[], '2026-09-26T15:00:00+00:00'::timestamptz),
  ('body-talk-awareness-log', 'Body Talk Awareness Log', 'worksheet'::resource_kind, 'Tracks how often a client hears or engages in appearance-focused talk across a day.', 'Build a client''s awareness of how much everyday talk centers on appearance.', array['Adults', 'Teens']::text[], 'Ongoing, brief entries', 'Appearance-focused talk is so common it often goes unnoticed, which makes it hard for a client to see how much of their day is shaped by it. Logging a few moments across a day, a comment overheard, a thought about how something looked, a compliment given, builds awareness of the pattern, which is usually the first step toward choosing a different kind of conversation.', '[{"id": "f0", "type": "textarea", "label": "A moment I noticed appearance-focused talk today"}, {"id": "f1", "type": "textarea", "label": "Where it came from, myself or someone else"}, {"id": "f2", "type": "textarea", "label": "How it affected my mood"}, {"id": "f3", "type": "textarea", "label": "A non-appearance topic I could bring up instead next time"}]'::jsonb, array['body image', 'self-monitoring', 'habits']::text[], '2026-09-26T15:00:00+00:00'::timestamptz)
